window.JLPT=window.JLPT||{};window.JLPT[10]={"week":10,"days":[{"day":0,"title":"단문 독해·글의 문법 푸는 법","vocab":[{"w":"お知らせ","r":"おしらせ","m":"알림, 공지","au":"56ac6ff23178"},{"w":"あんない","r":"あんない","m":"안내 (案内)","au":"2345cabfedb6","rep":1},{"w":"集合","r":"しゅうごう","m":"집합, 모임","au":"79ee7e20dfd3"},{"w":"会場","r":"かいじょう","m":"행사장, 회장","au":"2d4b8af2b5e3","rep":1},{"w":"うけつけ","r":"うけつけ","m":"접수(처) (受付)","au":"71b9cda6b95d"},{"w":"開始","r":"かいし","m":"개시, 시작","au":"298d94fec29b"},{"w":"中止","r":"ちゅうし","m":"중지, (행사) 취소","au":"2cfb5c4c1480"},{"w":"注意","r":"ちゅうい","m":"주의","au":"5641cf64166c"},{"w":"れんらく","r":"れんらく","m":"연락 (連絡)","au":"c53a60bbc4e6","rep":1},{"w":"場所","r":"ばしょ","m":"장소","au":"dd4c81d93cac","rep":1},{"w":"持ち物","r":"もちもの","m":"소지품, 준비물","au":"891bafe686c7"},{"w":"用意","r":"ようい","m":"준비 (用意する: 준비하다)","au":"b47b5bdda8eb","rep":1},{"w":"説明会","r":"せつめいかい","m":"설명회","au":"e66020236e96"},{"w":"以上","r":"いじょう","m":"이상 (그 수 포함)","au":"c9a1901fd990"},{"w":"以下","r":"いか","m":"이하 (그 수 포함)","au":"adde6b1541fc"}],"lesson":{"summary":"단문(메모·메일·안내문)은 질문을 먼저 읽고 지문에서 근거 문장을 찾는 것이 핵심입니다. 글의 문법은 빈칸 앞뒤 문장의 흐름(접속사·문말·시제)을 보고 고릅니다.","points":["短文 푸는 순서: ① 질문을 먼저 읽는다 → ② 누가 누구에게 쓴 글인지 확인 → ③ 질문과 관련된 문장을 찾는다 → ④ 보기와 내용을 비교. 한 문제 2~3분.","함정 1: 지문의 단어가 그대로 들어간 보기가 오답인 경우가 많습니다. 단어가 아니라 「내용」이 맞는지 확인하세요.","함정 2: 계획이 바뀌는 글. 「～でしたが」「でも」「ところが」 뒤에 진짜 정보가 옵니다. 메일·메모에서는 「～てください」「～までに」 문장이 정답의 근거인 경우가 많습니다.","文章の文法: 빈칸 앞뒤 한 문장씩 읽고 ① 접속사(それで・でも・たとえば) ② 문말(～と思います・～そうです・～ようです) ③ 시제(る형/た형) ④ 수수·수동 중 무엇을 묻는지 판단합니다.","글쓴이 입장에서 생각하기: 남에게 들은 정보는 「～そうです」, 자기가 정한 일은 「～ことにしました」, 남이 나에게 해 준 일은 「～てくれました」."],"table":{"head":["질문 형태","찾아야 할 곳"],"rows":[["「～は 何を しなければ なりませんか」","～てください / ～までに / ～ないでください"],["「どうして ～か」","～から / ～ので / それで 앞 문장"],["「いつ / どこ」","날짜·시각·장소, 그리고 「かわりました」 같은 변경 문장"],["「いちばん 言いたい ことは」","글의 마지막 부탁·주의 문장"]]},"examples":[{"jp":"あしたの 説明会は 十時からでしたが、十一時に かわりました。","r":"あしたの せつめいかいは じゅうじからでしたが、じゅういちじに かわりました。","ko":"내일 설명회는 10시부터였는데 11시로 바뀌었습니다.","au":"eaccbf11d88a"},{"jp":"金曜日までに へんじを ください。","r":"きんようびまでに へんじを ください。","ko":"금요일까지 답장을 주세요.","au":"3fe81f79f313"},{"jp":"雨が ふって いました。それで、出かけませんでした。","r":"あめが ふって いました。それで、でかけませんでした。","ko":"비가 오고 있었습니다. 그래서 외출하지 않았습니다.","au":"c647071cc8f5"},{"jp":"かさを 持って いくのを わすれないで ください。","r":"かさを もって いくのを わすれないで ください。","ko":"우산 가져가는 것을 잊지 마세요.","au":"11375493ddfe"}]},"drills":[{"part":"短文","q":"（台所の テーブルの 上に メモが あります。）<br>ゆいへ<br>お母さんは 今日、おばあちゃんの 家に 行きます。帰りは 8時ごろに なります。ばんごはんは れいぞうこに カレーが あるので、あたためて 食べて ください。それから、6時ごろ にもつが とどくので、うけとって おいて ください。おふろの そうじは しなくても いいです。<br>母<br><br>ゆいさんは 何を しなければ なりませんか。","choices":["カレーを 作って、にもつを 送る。","おばあちゃんの 家に 行って、おふろの そうじを する。","にもつを うけとって、おふろの そうじを する。","カレーを あたためて 食べて、にもつを うけとる。"],"a":3,"ex":"「あたためて 食べて ください」「うけとって おいて ください」가 해야 할 일입니다. 목욕탕 청소는 「しなくても いいです」(안 해도 됨)라서 오답."},{"part":"短文","q":"（学生が 先生から メールを もらいました。）<br>みなさん<br>来週の 月曜日の じゅぎょうは、教室が かわります。いつもの 301教室ではなく、502教室を 使います。時間は いつもと 同じです。教室の 場所が わからない 人は、1かいの じむしょで 聞いて ください。それから、しゅくだいの 作文は 月曜日に 出して ください。<br>田中<br><br>来週の 月曜日、学生は どう しますか。","choices":["いつもより 早く 502教室へ 行って、作文を 出す。","いつもと 同じ 時間に 301教室へ 行って、作文を 出す。","いつもと 同じ 時間に 502教室へ 行って、作文を 出す。","いつもと 同じ 時間に じむしょへ 行って、作文を 出す。"],"a":2,"ex":"교실만 301→502로 바뀌고 시간은 「いつもと 同じ」입니다. 사무실은 교실 위치를 모를 때만 가는 곳이라 오답."},{"part":"短文","q":"（マンションの 入口に この お知らせが はって あります。）<br>お知らせ<br>11月19日（水）の 午前9時から 午後3時まで、水道の 工事が あります。この 間は 水が 使えません。前の 日に、飲む 水などを 用意して おいて ください。ごめいわくを おかけしますが、よろしく おねがいします。<br>かんりにん<br><br>この お知らせで いちばん 言いたい ことは 何ですか。","choices":["19日の 9時から 3時までは 水が 使えないので、水を 用意して おいて ほしい。","19日は 工事が あるので、マンションの 外に 出ないで ほしい。","19日は 工事の 音が 大きいので、家に いないで ほしい。","19日の 工事の 前に、水道を 自分で しらべて ほしい。"],"a":0,"ex":"공지의 핵심은 9시~3시에 물이 안 나오니 전날 물을 준비해 두라는 것입니다. 소리·외출 이야기는 지문에 없습니다."},{"part":"短文","q":"（店の 前に この 紙が はって あります。）<br>いつも ありがとう ございます。<br>店の 中の 工事の ため、12月1日（月）から 12月7日（日）まで 店を 休みます。12月8日（月）から また 開けます。休みの 間も、電話で ケーキの よやくが できます。<br>パンの 店 さくら<br><br>この 店に ついて 正しい ものは どれですか。","choices":["12月7日から また パンが 買える。","12月8日から また パンが 買える。","休みの 間は、電話でも ケーキの よやくが できない。","12月は ずっと 店が 休みだ。"],"a":1,"ex":"1일~7일 휴업, 「12月8日（月）から また 開けます」. 휴업 중에도 「電話で ケーキの よやくが できます」라서 세 번째 보기는 오답."},{"part":"短文","q":"（会社で 山下さんが この メールを 読みました。）<br>山下さん<br>あしたの 2時に 東京の 会社の 人が 3人 来ます。2かいの 小さい へやで 話を するので、それまでに いすを 5つ ならべて おいて ください。お茶は わたしが 用意します。しりょうの コピーは もう できて います。<br>木村<br><br>山下さんは あしたの 2時までに 何を しますか。","choices":["へやに いすを 3つ ならべる。","お茶を 用意する。","へやに いすを 5つ ならべる。","しりょうの コピーを する。"],"a":2,"ex":"「いすを 5つ ならべて おいて ください」가 부탁입니다. 3명은 손님 수, 차는 木村 씨가 준비, 복사는 이미 끝났습니다."},{"part":"短文","q":"（大学の けいじばんに この 紙が はって あります。）<br>りゅうがくせいの みなさんへ<br>12月13日（土）に 料理パーティーを します。自分の 国の 料理を 一つ 作って 持って きて ください。飲み物は 大学が 用意します。さんかしたい 人は、12月10日（水）までに 2かいの うけつけで 名前を 書いて ください。<br>りゅうがくせいセンター<br><br>パーティーに 出たい 人は、まず 何を しなければ なりませんか。","choices":["10日までに うけつけで 名前を 書く。","13日に 飲み物を 持って いく。","10日までに 国の 料理を うけつけに 持って いく。","13日に うけつけで 名前を 書く。"],"a":0,"ex":"「まず」 할 일은 10일까지 접수처에서 이름 쓰기(신청)입니다. 음료는 대학이 준비하고, 요리는 13일 파티에 가져갑니다."},{"part":"文章の文法","q":"先月、近所の こうえんに お知らせが はって ありました。「日曜日の 朝、みんなで こうえんを そうじしませんか」と 書いて ありました。わたしは 日本人と 話す チャンスだと 思って、<b>[ 1 ]<\/b>。その 日は 30人ぐらい 集まりました。そうじの 後で、みんなで お茶を 飲みながら たくさん 話しました。[ 2 ]、近所の 人と 友だちに なれました。<br><br><b>[ 1 ]<\/b>に 入る ものは どれですか。","choices":["行かない ことに しました","行って みた ことが ありません","行って みて ほしいです","行って みる ことに しました"],"a":3,"ex":"자기가 결정한 일이므로 「～ことにしました」. 뒤에 실제로 참가한 이야기가 이어지므로 「行かない ことに しました」·「行って みた ことが ありません」은 맞지 않습니다."},{"part":"文章の文法","q":"先月、近所の こうえんに お知らせが はって ありました。「日曜日の 朝、みんなで こうえんを そうじしませんか」と 書いて ありました。わたしは 日本人と 話す チャンスだと 思って、[ 1 ]。その 日は 30人ぐらい 集まりました。そうじの 後で、みんなで お茶を 飲みながら たくさん 話しました。<b>[ 2 ]<\/b>、近所の 人と 友だちに なれました。<br><br><b>[ 2 ]<\/b>に 入る ものは どれですか。","choices":["でも","それで","それとも","たとえば"],"a":1,"ex":"함께 이야기를 많이 나눈 결과 이웃과 친구가 되었으므로 결과의 「それで」. 「でも」는 반대 내용일 때 씁니다."},{"part":"文章の文法","q":"わたしの アパートの 近くに 新しい スーパーが できました。駅前で もらった ちらしに よると、オープンの 日は 野菜が ぜんぶ 半分の ねだんに <b>[ 3 ]<\/b>。それで、わたしは 朝 早く 行きました。でも、店の 前には もう 長い れつが できて いました。わたしが 店に 入った ときには、安い 野菜は [ 4 ]。とても ざんねんでした。<br><br><b>[ 3 ]<\/b>に 入る ものは どれですか。","choices":["なりそうです","なる つもりです","なって しまいました","なるそうです"],"a":3,"ex":"「ちらしに よると」(전단지에 따르면)는 전문 「～そうです」와 짝입니다. 「なりそうです」(~할 것 같다)는 양태라서 오답."},{"part":"文章の文法","q":"わたしの アパートの 近くに 新しい スーパーが できました。駅前で もらった ちらしに よると、オープンの 日は 野菜が ぜんぶ 半分の ねだんに [ 3 ]。それで、わたしは 朝 早く 行きました。でも、店の 前には もう 長い れつが できて いました。わたしが 店に 入った ときには、安い 野菜は <b>[ 4 ]<\/b>。とても ざんねんでした。<br><br><b>[ 4 ]<\/b>に 入る ものは どれですか。","choices":["もう ぜんぶ 売れて しまって いました","まだ たくさん のこって いました","売って あげました","売る つもりでした"],"a":0,"ex":"긴 줄이 있었고 마지막에 「ざんねんでした」라고 했으므로 이미 다 팔린 상태입니다. 「まだ のこって いました」는 아쉬움과 맞지 않습니다."},{"part":"読み","q":"あしたの 朝 8時に 駅の 前に <u>集合<\/u>して ください。","choices":["しゅうごお","しゅうごう","しゅごう","しゅうあい"],"a":1,"ex":"集合은 しゅうごう(장음 두 개). 「しゅごう」처럼 장음을 빼먹는 함정에 주의."},{"part":"読み","q":"雨の ため、今日の しあいは <u>中止<\/u>に なりました。","choices":["ちゅうじ","じゅうし","ちゅうし","なかし"],"a":2,"ex":"中止는 ちゅうし(중지·취소). 止는 し로 탁음이 붙지 않습니다."},{"part":"表記","q":"説明会の <u>かいじょう<\/u>は 2かいの 大きい へやです。","choices":["会揚","回場","会場","会湯"],"a":2,"ex":"かいじょう(행사장)는 会場. 揚·湯는 場와 모양이 비슷한 다른 한자입니다."},{"part":"文脈","q":"山に 行く ときは、天気に （　　）して ください。","choices":["用意","中止","集合","注意"],"a":3,"ex":"「天気に 注意する」(날씨에 주의하다). 用意는 「～を 用意する」(~을 준비하다) 형태라 조사 に와 맞지 않습니다."},{"part":"文脈","q":"あしたの 遠足の （　　）は おべんとうと 飲み物と かさです。","choices":["場所","持ち物","以上","開始"],"a":1,"ex":"도시락·음료·우산은 가져갈 물건이므로 持ち物(소지품, 준비물)."},{"part":"言い換え","q":"この パーティーは <u>20さい 以上の 人<\/u>が さんか できます。","choices":["20さいと 20さいより 上の 人","20さいより 上の 人だけ","20さいより 下の 人","20さいと 20さいより 下の 人"],"a":0,"ex":"以上은 그 숫자를 포함합니다. 20세도 참가 가능하므로 「20さいより 上の 人だけ」는 오답."},{"part":"文法形式","q":"ドアに 「さわらないで ください」と 書いて あります。この ドアは （　　） いけません。","choices":["さわらなくては","さわっても","さわっては","さわらなければ"],"a":2,"ex":"「～ては いけません」(~하면 안 됩니다)는 금지. 「さわらなくては いけません」은 반대로 '만져야 한다'는 뜻입니다."},{"part":"文法形式","q":"メールに よると、あしたの 説明会は 1時間 早く （　　）。","choices":["始まるそうです","始まりそうです","始まる ことに します","始まって みます"],"a":0,"ex":"「～に よると」 + 전문 「사전형＋そうです」. 「始まりそうです」는 눈으로 보고 하는 추측(양태)입니다."},{"part":"文法形式","q":"この お知らせは 日本語と 英語で （　　） います。","choices":["書いて","書かせて","書かされて","書かれて"],"a":3,"ex":"주어가 「お知らせ」(공지)이므로 수동 「書かれて いる」(쓰여 있다). 「書いて いる」는 사람이 주어일 때."},{"part":"文法形式","q":"うけつけで 名前を 書いて （　　）、会場に 入って ください。","choices":["まで","から","ながら","ために"],"a":1,"ex":"「～てから」(~하고 나서). 이름을 먼저 쓰고 그다음 입장하는 순서입니다. ながら·ために는 て형에 붙지 않습니다."}],"shadow":{"jp":"質問を 先に 読んでから、メールを 読みましょう。","r":"しつもんを さきに よんでから、メールを よみましょう。","ko":"질문을 먼저 읽고 나서 메일을 읽읍시다.","au":"ce03567450d7"}},{"day":1,"title":"중문 독해·접속사 흐름 잡기","vocab":[{"w":"まつり","r":"まつり","m":"축제 (祭り)","au":"db803b2629be"},{"w":"花火","r":"はなび","m":"불꽃놀이","au":"dccdf0a90267"},{"w":"大会","r":"たいかい","m":"대회","au":"69087ec8d484"},{"w":"さんか","r":"さんか","m":"참가 (参加)","au":"2029dab7c596"},{"w":"楽しみ","r":"たのしみ","m":"기대, 즐거움","au":"ecf98f20dee6","rep":1},{"w":"思い出","r":"おもいで","m":"추억","au":"82b4656621b7"},{"w":"けいけん","r":"けいけん","m":"경험 (経験)","au":"fdb5f671b3e5"},{"w":"気持ち","r":"きもち","m":"기분, 마음","au":"0f10e392e87e","rep":1},{"w":"かんじる","r":"かんじる","m":"느끼다 (感じる)","au":"891ae04a6c9c"},{"w":"集まる","r":"あつまる","m":"모이다","au":"3b1ea177a6cb","rep":1},{"w":"きめる","r":"きめる","m":"정하다 (決める)","au":"9ced0ba06f4f"},{"w":"じゅんび","r":"じゅんび","m":"준비 (準備)","au":"974821b11d5c","rep":1},{"w":"かつどう","r":"かつどう","m":"활동 (活動)","au":"9270d895a3e8"},{"w":"近所","r":"きんじょ","m":"근처, 이웃","au":"ec385189dd31"},{"w":"会話","r":"かいわ","m":"회화, 대화","au":"cc1dc5b426cd"}],"lesson":{"summary":"중문(일기·에세이 250~400자)은 문단마다 무엇을 말하는지 짧게 정리하며 읽습니다. 질문 순서는 대개 글의 순서와 같습니다.","points":["순서: 첫 번째 질문만 읽기 → 그 부분까지 읽고 풀기 → 다음 질문 읽고 이어서 읽기. 지문 하나에 5~6분.","「どうして」 문제는 「～ので」「～から」「それで」 근처, 「どう 思いましたか」 문제는 「～と 思いました」「～て よかったです」「～たいです」 문장에서 답을 찾습니다.","사실(무엇을 했다)과 생각(어떻게 느꼈다)을 구분하세요. 지문에 나온 사실이지만 질문과 관계없는 보기가 대표적인 함정입니다.","「はじめは ～と 思って いましたが」「ところが」 뒤에 글쓴이가 새로 알게 된 것(결론)이 옵니다.","접속사로 흐름 잡기: でも(반대) / それで(결과) / それに(추가) / たとえば(예) / すると(그러자) / ところが(예상과 다르게)."],"table":{"head":["접속사","뜻","뒤에 오는 내용"],"rows":[["でも / しかし","하지만","앞과 반대"],["それで / だから","그래서","앞의 결과"],["それに","게다가","같은 방향의 추가"],["すると","그러자","어떤 행동 뒤에 일어난 일"],["ところが","그런데","예상과 다른 일"],["たとえば","예를 들면","예시"]]},"examples":[{"jp":"はじめは むずかしいと 思って いました。でも、やって みると おもしろかったです。","r":"はじめは むずかしいと おもって いました。でも、やって みると おもしろかったです。","ko":"처음에는 어렵다고 생각했습니다. 하지만 해 보니 재미있었습니다.","au":"02e1f725bc0e"},{"jp":"かぎを なくしました。それで、家に 入れませんでした。","r":"かぎを なくしました。それで、いえに はいれませんでした。","ko":"열쇠를 잃어버렸습니다. 그래서 집에 들어갈 수 없었습니다.","au":"7aa5f8ad6532"},{"jp":"ドアを 開けました。すると、ねこが 入って きました。","r":"ドアを あけました。すると、ねこが はいって きました。","ko":"문을 열었습니다. 그러자 고양이가 들어왔습니다.","au":"ef59cadb016c"},{"jp":"この まつりは 楽しいです。それに、食べ物も おいしいです。","r":"この まつりは たのしいです。それに、たべものも おいしいです。","ko":"이 축제는 즐겁습니다. 게다가 음식도 맛있습니다.","au":"054c9fe8f72c"}]},"drills":[{"part":"中文","q":"（りゅうがくせいが 書いた 作文です。）<br>わたしの アパートの 近くで、毎年 夏に 小さい まつりが あります。今年は 近所に 住んで いる 田中さんに さそわれて、はじめて 行きました。<br>はじめは、日本語が あまり 上手では ないので、少し しんぱいでした。でも、会場に 行くと、田中さんが 近所の 人たちを しょうかいして くれました。みんな やさしくて、ゆっくり 話して くれたので、うれしかったです。夜は こうえんに 人が たくさん 集まって、いっしょに おどりました。おどりは むずかしかったですが、となりの おばあさんが 教えて くれました。<br>国に いた ときは、近所の 人と 話す ことが ほとんど ありませんでした。この まつりに さんかして、近所に 知って いる 人が できました。来年は、まつりの じゅんびから てつだいたいと 思って います。<br><br>はじめ、「わたし」は どうして しんぱいでしたか。","choices":["日本語が あまり 上手では なかったから","まつりの 会場の 場所が わからなかったから","おどりが できなかったから","田中さんが いっしょに 行けなかったから"],"a":0,"ex":"「日本語が あまり 上手では ないので、少し しんぱいでした」가 근거. 춤이 어려웠던 것은 나중 이야기이고 걱정한 이유가 아닙니다."},{"part":"中文","q":"（りゅうがくせいが 書いた 作文です。）<br>わたしの アパートの 近くで、毎年 夏に 小さい まつりが あります。今年は 近所に 住んで いる 田中さんに さそわれて、はじめて 行きました。<br>はじめは、日本語が あまり 上手では ないので、少し しんぱいでした。でも、会場に 行くと、田中さんが 近所の 人たちを しょうかいして くれました。みんな やさしくて、ゆっくり 話して くれたので、うれしかったです。夜は こうえんに 人が たくさん 集まって、いっしょに おどりました。おどりは むずかしかったですが、となりの おばあさんが 教えて くれました。<br>国に いた ときは、近所の 人と 話す ことが ほとんど ありませんでした。この まつりに さんかして、近所に 知って いる 人が できました。来年は、まつりの じゅんびから てつだいたいと 思って います。<br><br>「わたし」が 来年 したい ことは 何ですか。","choices":["近所の 人に おどりを 教える こと","まつりの じゅんびを てつだう こと","国の 近所の 人と 話す こと","田中さんを まつりに さそう こと"],"a":1,"ex":"마지막 문장 「来年は、まつりの じゅんびから てつだいたい」. 춤은 할머니에게 배운 것이지 가르치는 것이 아닙니다."},{"part":"中文","q":"（会社員が 書いた 作文です。）<br>先月、駅で 料理教室の ちらしを もらいました。「はじめての 人は むりょう」と 書いて あったので、すぐに 電話で もうしこみました。<br>教室の 日、わたしは 自分で 作った 料理を たくさん 食べられると 思って、朝ごはんを 食べないで 行きました。ところが、その 日は 先生が 料理を 作るのを 見る だけで、自分で 作る ことは できませんでした。さいごに 少し 食べましたが、とても おなかが すきました。<br>でも、先生の 説明は とても わかりやすくて、家でも 作れそうな 料理でした。次の 日、家で 同じ 料理を 作って みると、家族が 「おいしい」と 言って くれました。今は、毎月 その 教室に 通って います。<br><br>「わたし」は どうして おなかが すきましたか。","choices":["教室で 料理を 作るのに 時間が かかったから","自分で 作った 料理が おいしくなかったから","朝ごはんを 食べないで 行ったのに、教室では 少ししか 食べられなかったから","教室の 料理が 高くて、買えなかったから"],"a":2,"ex":"많이 먹을 줄 알고 아침을 거르고 갔는데(「ところが」) 보기만 하고 마지막에 조금 먹었을 뿐입니다. 직접 만들지는 않았으므로 첫 번째·두 번째 보기는 오답입니다."},{"part":"中文","q":"（会社員が 書いた 作文です。）<br>先月、駅で 料理教室の ちらしを もらいました。「はじめての 人は むりょう」と 書いて あったので、すぐに 電話で もうしこみました。<br>教室の 日、わたしは 自分で 作った 料理を たくさん 食べられると 思って、朝ごはんを 食べないで 行きました。ところが、その 日は 先生が 料理を 作るのを 見る だけで、自分で 作る ことは できませんでした。さいごに 少し 食べましたが、とても おなかが すきました。<br>でも、先生の 説明は とても わかりやすくて、家でも 作れそうな 料理でした。次の 日、家で 同じ 料理を 作って みると、家族が 「おいしい」と 言って くれました。今は、毎月 その 教室に 通って います。<br><br>この 人は 料理教室に ついて、今 どう して いますか。","choices":["自分で 作れないので、もう 行きたくないと 思って いる。","ずっと むりょうなので、毎月 通って いる。","料理を たくさん 食べられるので、楽しみに して いる。","先生の 説明が わかりやすいので、毎月 通って いる。"],"a":3,"ex":"설명이 알기 쉬웠고 「今は、毎月 その 教室に 通って います」. 무료는 처음 온 사람만이라 「ずっと むりょう」는 함정."},{"part":"中文","q":"（大学生が 書いた 作文です。）<br>去年の 秋、わたしは 町の マラソン大会で ボランティアを しました。仕事は、走って いる 人に 水を わたす ことでした。<br>朝 7時に 会場に 集まって、かかりの 人から 説明を 聞きました。大会が 始まると、たくさんの 人が 走って きました。水を わたす とき、「ありがとう」と 言って くれる 人が 多くて、わたしも 元気に なりました。<br>いちばん 心に のこって いるのは、さいごに 走って きた おじいさんです。足が いたそうでしたが、ゆっくり 走って ゴールしました。会場の みんなが 大きい 声で おうえんしました。その おじいさんを 見て、わたしも あきらめないで がんばろうと 思いました。いい けいけんに なったので、今年も さんかする つもりです。<br><br>「わたし」の ボランティアの 仕事は 何でしたか。","choices":["大会の 前に 会場で 説明を する こと","走って いる 人に 水を わたす こと","走る 人を 大きい 声で おうえんする こと","ゴールした 人に 「ありがとう」と 言う こと"],"a":1,"ex":"「仕事は、走って いる 人に 水を わたす ことでした」. 설명은 들은 쪽이고, 응원은 모두가 한 일이지 맡은 일이 아닙니다."},{"part":"中文","q":"（大学生が 書いた 作文です。）<br>去年の 秋、わたしは 町の マラソン大会で ボランティアを しました。仕事は、走って いる 人に 水を わたす ことでした。<br>朝 7時に 会場に 集まって、かかりの 人から 説明を 聞きました。大会が 始まると、たくさんの 人が 走って きました。水を わたす とき、「ありがとう」と 言って くれる 人が 多くて、わたしも 元気に なりました。<br>いちばん 心に のこって いるのは、さいごに 走って きた おじいさんです。足が いたそうでしたが、ゆっくり 走って ゴールしました。会場の みんなが 大きい 声で おうえんしました。その おじいさんを 見て、わたしも あきらめないで がんばろうと 思いました。いい けいけんに なったので、今年も さんかする つもりです。<br><br>おじいさんを 見て、「わたし」は どう 思いましたか。","choices":["足が いたいなら、走らない ほうが いいと 思った。","来年は 自分も 大会で 走りたいと 思った。","自分も あきらめないで がんばろうと 思った。","ゆっくり 走るのは よくないと 思った。"],"a":2,"ex":"「わたしも あきらめないで がんばろうと 思いました」가 정답 문장. 올해도 참가할 생각이지만 「ボランティア」로서이지 달리는 것이 아닙니다."},{"part":"文章の文法","q":"わたしは 日本に 来て、ごみの 出し方に おどろきました。日本では、ごみを 出す 日が 曜日で きまって います。<b>[ 1 ]<\/b>、わたしの 町では もえる ごみは 火曜日と 金曜日、びんや かんは 水曜日です。はじめは よく わからなくて、何回も まちがえて しまいました。でも、となりの 人が ていねいに 教えて [ 2 ]。今は ちゃんと 出せる ように なりました。<br><br><b>[ 1 ]<\/b>に 入る ものは どれですか。","choices":["それで","でも","すると","たとえば"],"a":3,"ex":"앞 문장(요일별로 정해져 있다)의 구체적인 예가 이어지므로 「たとえば」(예를 들면)."},{"part":"文章の文法","q":"わたしは 日本に 来て、ごみの 出し方に おどろきました。日本では、ごみを 出す 日が 曜日で きまって います。[ 1 ]、わたしの 町では もえる ごみは 火曜日と 金曜日、びんや かんは 水曜日です。はじめは よく わからなくて、何回も まちがえて しまいました。でも、となりの 人が ていねいに 教えて <b>[ 2 ]<\/b>。今は ちゃんと 出せる ように なりました。<br><br><b>[ 2 ]<\/b>に 入る ものは どれですか。","choices":["くれました","あげました","やりました","さしあげました"],"a":0,"ex":"옆집 사람이 「わたし」에게 가르쳐 준 것이므로 「～て くれました」. あげる·やる·さしあげる는 내가 남에게 해 줄 때."},{"part":"文章の文法","q":"わたしの しゅみは 写真を とる ことです。先月、町の 写真大会に はじめて 作品を 出しました。自分では あまり 上手に とれなかったと 思って いました。<b>[ 3 ]<\/b>、先週 大会から 手紙が 来て、わたしの 写真が 2ばんに えらばれた ことが わかりました。とても うれしくて、すぐに 家族に [ 4 ]。<br><br><b>[ 3 ]<\/b>に 入る ものは どれですか。","choices":["だから","ところが","それに","たとえば"],"a":1,"ex":"잘 못 찍었다고 생각했는데 뜻밖에 2등. 예상과 다른 결과이므로 「ところが」."},{"part":"文章の文法","q":"わたしの しゅみは 写真を とる ことです。先月、町の 写真大会に はじめて 作品を 出しました。自分では あまり 上手に とれなかったと 思って いました。[ 3 ]、先週 大会から 手紙が 来て、わたしの 写真が 2ばんに えらばれた ことが わかりました。とても うれしくて、すぐに 家族に <b>[ 4 ]<\/b>。<br><br><b>[ 4 ]<\/b>に 入る ものは どれですか。","choices":["知らせられました","知らせて もらいました","知らせて くれました","知らせました"],"a":3,"ex":"기뻐서 내가 가족에게 알린 것이므로 능동 「知らせました」. 「知らせて もらいました」는 남에게 알려 달라고 한 뜻이 됩니다."},{"part":"読み","q":"夏休みの <u>思い出<\/u>を 作文に 書きました。","choices":["おもいで","おもいだ","おもいて","しいで"],"a":0,"ex":"思い出는 おもいで(추억). 思い出す(おもいだす, 생각해 내다)와 헷갈리지 마세요."},{"part":"表記","q":"近所の 人が こうえんに <u>あつまって<\/u> います。","choices":["集つまって","習まって","集まって","終まって"],"a":2,"ex":"あつまる는 集まる. 「集つまる」는 오쿠리가나가 틀린 표기입니다."},{"part":"文脈","q":"あしたの 旅行が （　　）で、今夜は なかなか ねむれません。","choices":["思い出","気持ち","会話","楽しみ"],"a":3,"ex":"「～が 楽しみで ねむれない」(~가 기대돼서 잠이 안 온다). 思い出는 지난 일에 씁니다."},{"part":"文脈","q":"テストの 前に、ちゃんと （　　）を して おきましょう。","choices":["かつどう","けいけん","じゅんび","まつり"],"a":2,"ex":"「じゅんびを して おく」(준비해 두다). 시험 전에 미리 하는 것은 준비입니다."},{"part":"用法","q":"「けいけん」の 使い方として いちばん いいものを えらんで ください。","choices":["外国で はたらいた けいけんが あります。","毎朝 けいけんを 飲んでから 出かけます。","この ケーキは けいけんが あって おいしいです。","駅の けいけんで 友だちを 待ちました。"],"a":0,"ex":"けいけん(경험)은 「～た けいけんが ある」(~한 경험이 있다)처럼 씁니다. 나머지는 마실 것·맛·장소에 잘못 썼습니다."},{"part":"文法形式","q":"日本に 来てから、なっとうが 食べられる （　　）。","choices":["ことに しました","ように なりました","つもりでした","ところでした"],"a":1,"ex":"「가능형＋ように なる」는 능력·습관의 변화(~할 수 있게 되었다). 「日本に 来てから」가 변화의 힌트."},{"part":"文法形式","q":"まつりの 日は 雨が ふる （　　）、かさを 持って 行きました。","choices":["かもしれないので","はずなのに","ように","ところ"],"a":0,"ex":"비가 올지도 모르니까 우산을 가져갔다는 이유 관계. 「はずなのに」는 역접이라 뒷문장과 맞지 않습니다."},{"part":"文法形式","q":"わたしは 大会に 出る 前に、毎日 3キロ 走る （　　）。","choices":["そうです","ところでした","ようです","ことに しました"],"a":3,"ex":"자기가 결정한 일은 「～ことに しました」. 자기 일에 전문 「そうです」나 추측 「ようです」는 쓰지 않습니다."},{"part":"文法形式","q":"先生に 作文を 見て （　　）、まちがいが 3つ ありました。","choices":["あげたら","もらったら","くれたら","させたら"],"a":1,"ex":"「先生に ～て もらう」(선생님이 ~해 주다). 「～たら」는 해 보니 알게 된 사실. 「先生に ～て くれる」는 조사가 맞지 않습니다."},{"part":"文法形式","q":"あしたの 大会が ある （　　）、まだ わかりません。","choices":["かも","ように","かどうか","ために"],"a":2,"ex":"「～か どうか わからない」(~인지 아닌지 모른다). 간접의문 형태입니다."}],"shadow":{"jp":"はじめは しんぱいでしたが、さんかして よかったです。","r":"はじめは しんぱいでしたが、さんかして よかったです。","ko":"처음엔 걱정했지만 참가하길 잘했습니다.","au":"a00296cd40fe"}},{"day":2,"title":"정보 검색·안내문 읽기","vocab":[{"w":"料金","r":"りょうきん","m":"요금","au":"a486a63ae1b0","rep":1},{"w":"むりょう","r":"むりょう","m":"무료 (無料)","au":"38f88f365bab"},{"w":"わりびき","r":"わりびき","m":"할인 (割引)","au":"b8b592a3037a","rep":1},{"w":"品物","r":"しなもの","m":"물건, 상품","au":"984f5a7a0920","rep":1},{"w":"売り場","r":"うりば","m":"매장, 파는 곳","au":"80b766cd3fc5","rep":1},{"w":"えいぎょう","r":"えいぎょう","m":"영업 (営業)","au":"0bb285de3db7"},{"w":"休館日","r":"きゅうかんび","m":"휴관일","au":"0562b7a63a1e"},{"w":"へいじつ","r":"へいじつ","m":"평일 (平日)","au":"008e0faa32d9"},{"w":"しゅうまつ","r":"しゅうまつ","m":"주말 (週末)","au":"25170665b902"},{"w":"もうしこむ","r":"もうしこむ","m":"신청하다 (申し込む)","au":"4ec2a5e4814a"},{"w":"よやく","r":"よやく","m":"예약 (予約)","au":"2800fb0e9b99","rep":1},{"w":"先着","r":"せんちゃく","m":"선착순","au":"88e38eb185eb"},{"w":"りよう","r":"りよう","m":"이용 (利用)","au":"156508433951"},{"w":"特別","r":"とくべつ","m":"특별","au":"749043f60a04","rep":1},{"w":"毎週","r":"まいしゅう","m":"매주","au":"157f7d7f2c2e"}],"lesson":{"summary":"정보 검색은 표·안내문에서 조건에 맞는 것을 고르는 문제입니다. 지문을 처음부터 다 읽지 말고, 질문의 조건부터 표시하세요.","points":["순서: ① 질문을 읽고 조건(요일·시간·나이·돈·인원)에 표시 → ② 표에서 그 조건에 해당하는 줄만 찾기 → ③ 조건을 하나씩 확인하며 안 맞는 보기 지우기.","※(주의) 표시, 「ただし」(단), 「～の 場合は」(~의 경우는) 같은 작은 글씨에 정답 열쇠가 숨어 있는 경우가 많습니다.","돈 계산: 어른·어린이 요금, 할인(わりびき), 단체 할인을 사람마다 따로 계산한 뒤 마지막에 더하기. 「～以上」「～以下」는 그 숫자 포함.","요일·기한: へいじつ(평일)=월~금, しゅうまつ(주말)=토·일. 休館日(휴관일)·しめきり(마감)를 꼭 확인.","시간 배분: 지문은 길어도 문제당 3분이면 충분합니다. 질문과 관계없는 줄은 읽지 않아도 됩니다."],"table":{"head":["표현","뜻"],"rows":[["以上 / 以下","이상 / 이하 (그 숫자 포함)"],["～まで / ～までに","~까지 계속 / ~까지(기한)"],["ただし","단, (예외 조건)"],["先着 ～名","선착순 ~명"],["むりょう / わりびき / ～円 引き","무료 / 할인 / ~엔 할인"],["しめきり","마감"]]},"examples":[{"jp":"子どもは 半分の 料金です。ただし、3さい 以下は むりょうです。","r":"こどもは はんぶんの りょうきんです。ただし、さんさい いかは むりょうです。","ko":"어린이는 반값입니다. 단, 3세 이하는 무료입니다.","au":"29db1d45b096"},{"jp":"もうしこみは 先着 20名までです。","r":"もうしこみは せんちゃく にじゅうめいまでです。","ko":"신청은 선착순 20명까지입니다.","au":"169e3ca3f3fd"},{"jp":"毎週 月曜日は 休館日です。","r":"まいしゅう げつようびは きゅうかんびです。","ko":"매주 월요일은 휴관일입니다.","au":"65a833c31eee"},{"jp":"へいじつは 夜 9時まで えいぎょうして います。","r":"へいじつは よる くじまで えいぎょうして います。","ko":"평일은 밤 9시까지 영업합니다.","au":"a6b9c6730cf7"}]},"drills":[{"part":"情報検索","q":"（市の スポーツセンターの あんないです。）<br>【スポーツセンター 秋の 教室】<br>① 水泳（大人）　火・木　19:00～20:30　1か月 4,000円<br>② 水泳（子ども 6～12さい）　土　10:00～11:00　1か月 3,000円<br>③ ヨガ　月・水　10:00～11:30　1か月 3,500円<br>④ テニス　土・日　9:00～11:00　1か月 5,500円<br>⑤ ダンス（中学生 以上）　金　17:30～19:00　1か月 3,000円<br>※ はじめての 人は、1か月目の 料金が 1,000円 わりびきに なります。<br>※ もうしこみは 1かいの うけつけで。しめきりは 10月25日です。<br><br>会社員の キムさんは 月曜日から 金曜日まで、9時から 6時まで 働いて います。仕事の 後か 週末に 教室に 入りたいです。料金は 1か月 4,000円 以下が いいです。キムさんが えらべる 教室は どれですか。","choices":["③ ヨガ","④ テニス","⑤ ダンス","① 水泳（大人）"],"a":3,"ex":"①은 화·목 19시 시작, 4,000엔(以下는 4,000 포함)이라 조건에 맞습니다. ③은 평일 오전, ④는 5,500엔(첫 달 할인을 받아도 4,500엔), ⑤는 17:30 시작이라 근무 시간과 겹칩니다."},{"part":"情報検索","q":"（市の スポーツセンターの あんないです。）<br>【スポーツセンター 秋の 教室】<br>① 水泳（大人）　火・木　19:00～20:30　1か月 4,000円<br>② 水泳（子ども 6～12さい）　土　10:00～11:00　1か月 3,000円<br>③ ヨガ　月・水　10:00～11:30　1か月 3,500円<br>④ テニス　土・日　9:00～11:00　1か月 5,500円<br>⑤ ダンス（中学生 以上）　金　17:30～19:00　1か月 3,000円<br>※ はじめての 人は、1か月目の 料金が 1,000円 わりびきに なります。<br>※ もうしこみは 1かいの うけつけで。しめきりは 10月25日です。<br><br>高校生の ゆりさんは はじめて ダンス教室に 入ります。1か月目は いくら はらいますか。","choices":["2,000円","1,000円","3,000円","4,000円"],"a":0,"ex":"⑤ 댄스는 3,000엔, 처음인 사람은 첫 달 1,000엔 할인이므로 3,000−1,000＝2,000엔. 고등학생은 「中学生 以上」에 해당합니다."},{"part":"情報検索","q":"（図書館の あんないです。）<br>【みどり図書館 りようの あんない】<br>開館時間：火～金 9:00～19:00 ／ 土・日 9:00～17:00<br>休館日：毎週 月曜日<br>本：1人 10さつまで　2週間<br>ざっし：1人 3さつまで　1週間（今月の ざっしは 借りられません）<br>※ 図書館が 開いて いない ときは、入口の 横の ポストに 本を かえして ください。<br><br>山田さんは 土曜日の 午後5時半に 図書館に 行って、借りた 本を かえしたいです。どう すれば いいですか。","choices":["図書館の 中の カウンターで かえす。","入口の 横の ポストに 本を 入れる。","土曜日は かえせないので、月曜日に 行く。","図書館の 人に 電話して、開けて もらう。"],"a":1,"ex":"토요일은 17시까지라 17시 30분에는 닫혀 있습니다. ※에 따라 입구 옆 반납함에 넣습니다. 월요일은 휴관일이라 오답."},{"part":"情報検索","q":"（図書館の あんないです。）<br>【みどり図書館 りようの あんない】<br>開館時間：火～金 9:00～19:00 ／ 土・日 9:00～17:00<br>休館日：毎週 月曜日<br>本：1人 10さつまで　2週間<br>ざっし：1人 3さつまで　1週間（今月の ざっしは 借りられません）<br>※ 図書館が 開いて いない ときは、入口の 横の ポストに 本を かえして ください。<br><br>ジョンさんは 今日（水曜日）、本を 3さつと 先月の ざっしを 2さつ 借りました。ざっしは いつまでに かえさなければ なりませんか。","choices":["今週の 土曜日","来週の 月曜日","来週の 水曜日","さらいしゅうの 水曜日"],"a":2,"ex":"잡지는 1주일이므로 다음 주 수요일까지. 2주일(다다음 주 수요일)은 책의 기한이라 함정입니다."},{"part":"情報検索","q":"（動物公園の 入口に ある あんないです。）<br>【ふじ動物公園 料金】<br>大人（高校生 以上）　800円<br>子ども（小学生・中学生）　400円<br>小学生に なる 前の 子ども　むりょう<br>65さい 以上　400円<br>※ 10人 以上の グループは、ぜんいん 1人 100円 引きに なります。<br>※ 11月3日は 子ども（中学生まで）は むりょうです。<br><br>会社員の 父（40さい）、母（38さい）、中学生の 兄、5さいの 妹の 4人で、11月10日に 行きます。ぜんぶで いくら はらいますか。","choices":["1,600円","2,400円","2,000円","2,800円"],"a":2,"ex":"어른 800×2＝1,600엔, 중학생 400엔, 5세(초등학생 전)는 무료 → 2,000엔. 11월 3일이 아니므로 중학생 무료는 적용되지 않습니다."},{"part":"情報検索","q":"（動物公園の 入口に ある あんないです。）<br>【ふじ動物公園 料金】<br>大人（高校生 以上）　800円<br>子ども（小学生・中学生）　400円<br>小学生に なる 前の 子ども　むりょう<br>65さい 以上　400円<br>※ 10人 以上の グループは、ぜんいん 1人 100円 引きに なります。<br>※ 11月3日は 子ども（中学生まで）は むりょうです。<br><br>小学生 8人と 先生 2人、合わせて 10人で 行きます。ぜんぶで いくら はらいますか。","choices":["2,800円","3,800円","4,000円","4,800円"],"a":1,"ex":"10명 이상 단체라 1인당 100엔 할인: 어린이 300×8＝2,400엔, 어른 700×2＝1,400엔, 합계 3,800엔. 할인 전 금액 4,800엔은 함정."},{"part":"短文","q":"（コンビニの 入口に この 紙が はって あります。）<br>アルバイトを さがして います！<br>時間：①朝 6時～9時　②夜 5時～10時<br>週に 2日 以上 働ける 人。①の 時間に 働く 人は、じきゅうが 100円 高く なります。店の 人や お客さんと 日本語で 話せる 人を さがして います。くわしい ことは 店の 人に 聞いて ください。<br><br>この アルバイトに ついて 正しい ものは どれですか。","choices":["朝の 時間に 働くと、夜より じきゅうが 高い。","週に 1日だけ 働いても いい。","日本語が 話せなくても いい。","夜は 9時まで 働く。"],"a":0,"ex":"①(아침) 시간에 일하면 시급이 100엔 높습니다. 주 2일 이상, 일본어로 대화 가능해야 하고, 밤은 10시까지입니다."},{"part":"短文","q":"（リンさんが 友だちから メールを もらいました。）<br>リンさん<br>今週の 土曜日の バーベキューの ことですが、天気よほうに よると 雨が ふるそうです。それで、日曜日に する ことに しました。時間と 場所は 同じです。もし 日曜日に 来られなかったら、金曜日までに れんらくして ください。肉は こちらで 用意するので、飲み物を 持って きて ください。<br>まゆみ<br><br>リンさんは 日曜日に 行けます。リンさんは 何を しますか。","choices":["金曜日までに まゆみさんに れんらくする。","肉を 買って、土曜日に 行く。","雨なので、家で 待つ。","日曜日に 飲み物を 持って バーベキューに 行く。"],"a":3,"ex":"바비큐가 일요일로 바뀌었고 음료를 가져오라고 했습니다. 연락은 「来られなかったら」(못 올 때)만 하면 됩니다."},{"part":"短文","q":"（スーパーの レジの 前に この お知らせが あります。）<br>お客様へ<br>4月1日から、レジぶくろが ほしい 方は 1まい 5円 はらって ください。自分の かばんや ふくろを 持って きた 方には、ポイントを いつもの 2ばいに します。ただし、ポイントカードを わすれた 場合は、ポイントは つきません。<br><br>4月1日から、ポイントが いつもより 多く もらえるのは どんな 人ですか。","choices":["レジぶくろを 5円で 買った 人","自分の ふくろを 持って きたが、ポイントカードを わすれた 人","レジぶくろを 2まい 買った 人","自分の ふくろを 持って きて、ポイントカードも 持って いる 人"],"a":3,"ex":"자기 장바구니를 가져오면 포인트 2배. 단 「ただし」 이하에 카드를 잊으면 포인트가 안 붙는다고 했습니다."},{"part":"短文","q":"（市の ホームページに この お知らせが あります。）<br>「親子で 作ろう！ 木の おもちゃ」<br>12月7日（日）13:00～15:00　市民センター 3がい<br>小学生と その 家族が さんか できます。ざいりょうの お金は いりません。先着 15くみです。はさみを 持って きて ください。もうしこみは 11月30日までに 電話で おねがいします。<br><br>この イベントに さんかしたい 人は どう しますか。","choices":["12月7日に 会場で もうしこんで、はさみを 持って いく。","11月30日までに 電話で もうしこんで、ざいりょうの お金を 持って いく。","11月30日までに 電話で もうしこんで、その 日は はさみを 持って いく。","小学生だけで 12月7日に 会場へ 行く。"],"a":2,"ex":"신청은 11월 30일까지 전화, 가위를 지참. 재료비는 「いりません」이고 초등학생과 가족이 함께 참가합니다."},{"part":"読み","q":"毎週 水曜日は 図書館の <u>休館日<\/u>です。","choices":["きゅうかんび","きゅうかんにち","やすみかんび","きゅかんび"],"a":0,"ex":"休館日은 きゅうかんび. 日을 にち로 읽는 함정, 장음 빠뜨리는 함정에 주의."},{"part":"読み","q":"この 店で 売って いる <u>品物<\/u>は ぜんぶ 100円です。","choices":["ひんもの","しなもの","しなぶつ","ひんぶつ"],"a":1,"ex":"品物는 훈독끼리 합쳐 しなもの. 品(ひん)·物(ぶつ) 음독 조합은 함정입니다."},{"part":"表記","q":"この デパートは くつの <u>うりば<\/u>が 広いです。","choices":["買い場","売り場","売り揚","売り湯"],"a":1,"ex":"うりば(매장)는 「売る(팔다)＋場」. 買う는 かう라 읽기가 다르고, 揚·湯는 場와 비슷한 다른 한자입니다."},{"part":"文脈","q":"この カードを 見せると、ケーキが 100円 安く なります。この （　　）は 今月だけです。","choices":["わりびき","よやく","休館日","料金"],"a":0,"ex":"100엔 싸지는 것은 わりびき(할인). 「料金は 今月だけ」는 뜻이 통하지 않습니다."},{"part":"言い換え","q":"この 店は <u>へいじつ<\/u>は 夜 8時まで 開いて います。","choices":["土曜日と 日曜日は","毎日","休みの 日は","月曜日から 金曜日までは"],"a":3,"ex":"へいじつ(평일)는 월~금. 토·일은 しゅうまつ(주말)입니다."},{"part":"文法形式","q":"図書館の 本は 来週の 金曜日 （　　） かえして ください。","choices":["まで","ので","までに","ながら"],"a":2,"ex":"기한까지 한 번 하는 동작은 「までに」. 「まで」는 그때까지 계속하는 동작에 씁니다."},{"part":"文法形式","q":"この 店は 品物が 安い （　　）、店の 人も しんせつです。","choices":["のに","し","ても","ために"],"a":1,"ex":"좋은 점을 나열하는 「～し」(~하고). 「のに」는 역접이라 「しんせつ」와 이어지지 않습니다."},{"part":"文法形式","q":"この カードを （　　）、むりょうで 入れます。","choices":["見せても","見せたのに","見せながら","見せれば"],"a":3,"ex":"조건 「～ば」(~하면). 「見せても」는 '보여 줘도'라는 역접이라 뜻이 맞지 않습니다."},{"part":"組み立て","q":"A「すみません、くつの 売り場は どこですか。」<br>B「くつは 3がいです。エレベーターを ＿＿ ＿＿ <b>★<\/b> ＿＿ あります。」","choices":["まがった","おりて","右に","ところに"],"a":0,"ex":"완성: 「エレベーターを おりて 右に まがった ところに あります。」 ★은 세 번째 「まがった」."},{"part":"組み立て","q":"A「来週の 説明会、もう もうしこみましたか。」<br>B「いいえ。インターネットで ＿＿ ＿＿ <b>★<\/b> ＿＿ わからないんです。」","choices":["どう","もうしこめば","いいか","よく"],"a":2,"ex":"완성: 「インターネットで どう もうしこめば いいか よく わからないんです。」 ★은 세 번째 「いいか」."}],"shadow":{"jp":"質問を 読んでから、ひょうの 中で 曜日と 時間を さがします。","r":"しつもんを よんでから、ひょうの なかで ようびと じかんを さがします。","ko":"질문을 읽고 나서 표 안에서 요일과 시간을 찾습니다.","au":"0ba909878ca0"}},{"day":3,"title":"과제 이해·포인트 이해 듣기","vocab":[{"w":"アナウンス","r":"アナウンス","m":"안내 방송","au":"250e3163e4c0"},{"w":"おくれる","r":"おくれる","m":"늦다, 지각하다 (遅れる)","au":"78c15824ae25","rep":1},{"w":"出口","r":"でぐち","m":"출구","au":"f00a84954305"},{"w":"入口","r":"いりぐち","m":"입구","au":"bbbc4022c1b2"},{"w":"かいだん","r":"かいだん","m":"계단 (階段)","au":"c2f62fd9cff8"},{"w":"急ぐ","r":"いそぐ","m":"서두르다","au":"7ece65211754","rep":1},{"w":"間に合う","r":"まにあう","m":"시간에 늦지 않다, 제시간에 대다","au":"665ac851fb17","rep":1},{"w":"へんこう","r":"へんこう","m":"변경 (変更)","au":"4a22d0d224fb"},{"w":"かかりいん","r":"かかりいん","m":"담당 직원 (係員)","au":"f4aa5c1e5d0b"},{"w":"わすれもの","r":"わすれもの","m":"분실물, 두고 온 물건 (忘れ物)","au":"325d310f1674"},{"w":"よぶ","r":"よぶ","m":"부르다 (呼ぶ)","au":"1fa097cf91d2","rep":1},{"w":"もどる","r":"もどる","m":"되돌아가다 (戻る)","au":"a63a99606d6a","rep":1},{"w":"ならぶ","r":"ならぶ","m":"줄을 서다 (並ぶ)","au":"5182f7f3aba8"},{"w":"こむ","r":"こむ","m":"붐비다 (込む)","au":"cf73cff1ed19"},{"w":"足りる","r":"たりる","m":"충분하다, 족하다","au":"78eabbbeedc9","rep":1}],"lesson":{"summary":"과제 이해는 '이 다음에 (먼저) 할 일', 포인트 이해는 '이유·장소·시간' 같은 핵심 하나를 듣는 문제입니다. 처음 나오는 질문을 꼭 기억하고, 보기를 미리 읽어 두세요.","points":["課題理解: 첫 질문 「このあと まず 何を しますか」를 기억하고, 대화 중 나오는 여러 일 가운데 '이미 한 일'과 '안 해도 되는 일'을 지워 나갑니다.","課題理解 함정: 「～は もう ～ました」「～なくても いいです」「それは あとで いいです」가 들리면 그 보기는 오답. 「その 前に」「先に」「まず」 뒤가 정답 후보.","ポイント理解: 질문이 먼저 나오고 보기를 읽을 시간이 있습니다. 「どうして」「どこ」「何時」 중 무엇을 묻는지 표시해 두세요.","ポイント理解 함정: 처음 말한 이유·시간·장소가 나중에 바뀝니다. 「いえ」「でも」「じつは」 뒤를 집중해서 들으세요.","안내 방송(アナウンス)은 「～ばんせん」「～分 おくれて」「～階」 같은 숫자 정보와 「ご注意ください」 앞 내용을 메모합니다."],"table":{"head":["들리면 주의","의미"],"rows":[["～は もう ～ました","이미 했음 → 오답"],["～なくても いいです / あとで いいです","안 해도 됨·나중 → 오답"],["先に / まず / その 前に","먼저 할 일 → 정답 후보"],["じつは / 本当は","사실은 → 진짜 이유"],["いえ、～じゃなくて","정정 → 뒤가 정답"]]},"examples":[{"jp":"コピーは もう しました。","r":"コピーは もう しました。","ko":"복사는 이미 했습니다.","au":"bcf9f2073a52"},{"jp":"はこは あとで いいですから、先に いすを ならべて ください。","r":"はこは あとで いいですから、さきに いすを ならべて ください。","ko":"상자는 나중에 해도 되니까 먼저 의자를 놓아 주세요.","au":"ae2d8f3c322f"},{"jp":"じつは、駅で さいふを おとして しまったんです。","r":"じつは、えきで さいふを おとして しまったんです。","ko":"사실은 역에서 지갑을 떨어뜨렸거든요.","au":"42648035de60"},{"jp":"いえ、三時じゃなくて 四時です。","r":"いえ、さんじじゃなくて よじです。","ko":"아뇨, 3시가 아니라 4시입니다.","au":"0d2cf989d4d0"}]},"drills":[{"part":"課題理解","q":"男の人は このあと まず 何を しますか。","listen":[{"s":"N","t":"会社で 男の人と 女の人が 話しています。男の人は このあと まず 何を しますか。"},{"s":"F","t":"木村さん、あしたの 説明会の じゅんび、てつだって もらえますか。"},{"s":"M","t":"はい。何を すれば いいですか。いすを ならべましょうか。"},{"s":"F","t":"いすは あしたの 朝 ならべます。今日は しりょうを コピーして ほしいんです。五十まい おねがいします。"},{"s":"M","t":"わかりました。すぐ コピーします。"},{"s":"F","t":"あ、その 前に、会場の へやが 使えるか どうか、うけつけに 電話で 聞いて もらえますか。"},{"s":"M","t":"はい、わかりました。"},{"s":"N","t":"男の人は このあと まず 何を しますか。"}],"choices":["いすを ならべる","しりょうを コピーする","会場の へやを そうじする","うけつけに 電話を する"],"a":3,"ex":"여자가 「その 前に、～うけつけに 電話で 聞いて もらえますか」라고 해서 먼저 전화를 합니다. 의자는 내일 아침, 복사는 전화 다음입니다.","au":"ae72cddd7974"},{"part":"課題理解","q":"学生は 旅行に 行く ために、まず 何を しますか。","listen":[{"s":"N","t":"学校で 先生と 学生が 話しています。学生は 旅行に 行く ために、まず 何を しますか。"},{"s":"F","t":"リーさん、来月の 旅行に 行きますか。"},{"s":"M","t":"はい、行きたいです。もうしこみは どう すれば いいですか。"},{"s":"F","t":"この 紙に 名前と 電話ばんごうを 書いて、じむしょに 出して ください。お金は 旅行の 一週間前までに はらって ください。"},{"s":"M","t":"わかりました。紙は 今日 出しても いいですか。"},{"s":"F","t":"ええ。あ、パスポートの ばんごうも 書かなければ なりませんよ。"},{"s":"M","t":"パスポートは 家に あります。じゃ、家に 帰って ばんごうを 見てから 書きます。"},{"s":"N","t":"学生は 旅行に 行く ために、まず 何を しますか。"}],"choices":["もうしこみの 紙を じむしょに 出す","旅行の お金を はらう","パスポートの ばんごうを 見る","先生に 電話ばんごうを 教える"],"a":2,"ex":"종이에 여권 번호도 써야 하는데 여권이 집에 있어서 「家に 帰って ばんごうを 見てから 書きます」. 제출과 입금은 그다음입니다.","au":"c7e2dd43d618"},{"part":"課題理解","q":"男の人は 何を 買って きますか。","listen":[{"s":"N","t":"家で 女の人と 男の人が 話しています。男の人は 何を 買って きますか。"},{"s":"F","t":"今夜の パーティー、飲み物は ジュースと お茶で いいかな。"},{"s":"M","t":"ジュースは きのう 買って おいたよ。"},{"s":"F","t":"お茶は まだ ないの。それから、紙の コップも 足りないかもしれない。"},{"s":"M","t":"コップは 二十こ あるから だいじょうぶだよ。"},{"s":"F","t":"そう。じゃ、お茶だけ おねがい。ケーキは わたしが 帰りに 店で うけとって くるから。"},{"s":"N","t":"男の人は 何を 買って きますか。"}],"choices":["ジュース","お茶","紙の コップ","ケーキ"],"a":1,"ex":"주스는 어제 사 두었고 컵은 20개 있어서 괜찮으며 케이크는 여자가 가져옵니다. 「お茶だけ おねがい」.","au":"58057a7ab911"},{"part":"課題理解","q":"男の人は このあと 何を しますか。","listen":[{"s":"N","t":"病院の うけつけで 女の人と 男の人が 話しています。男の人は このあと 何を しますか。"},{"s":"F","t":"こんにちは。こちらの 病院は はじめてですか。"},{"s":"M","t":"はい、はじめてです。"},{"s":"F","t":"では、この 紙に 名前と 住所を 書いて ください。"},{"s":"M","t":"あのう、紙は もう 書きました。さっき 入口で もらったので。"},{"s":"F","t":"あ、そうですか。では、あちらで ねつを はかって ください。その あと、名前を よぶまで いすに すわって 待って いて ください。"},{"s":"N","t":"男の人は このあと 何を しますか。"}],"choices":["ねつを はかる","紙に 名前と 住所を 書く","いすに すわって 待つ","入口で 紙を もらう"],"a":0,"ex":"종이는 이미 썼다(「もう 書きました」)고 했고, 먼저 열을 잰 다음 의자에서 기다립니다.","au":"a2f3d25848ed"},{"part":"課題理解","q":"女の学生は あした 何を 持って いきますか。","listen":[{"s":"N","t":"大学で 男の学生と 女の学生が 話しています。女の学生は あした 何を 持って いきますか。"},{"s":"M","t":"あしたの ハイキング、おべんとうは 自分で 持って いくんだよね。"},{"s":"F","t":"ううん、おべんとうは 先生が 用意して くれるって。飲み物も あるそうだよ。"},{"s":"M","t":"そうなんだ。じゃあ、何も いらないのかな。"},{"s":"F","t":"午後から 雨が ふるかもしれないから、かさを 持って きて くださいって。"},{"s":"M","t":"うわぎは？山は さむいよ。"},{"s":"F","t":"うわぎは 先生が かして くれるから、いらないそうだよ。"},{"s":"N","t":"女の学生は あした 何を 持って いきますか。"}],"choices":["おべんとう","飲み物","うわぎ","かさ"],"a":3,"ex":"도시락과 음료는 선생님이 준비하고, 겉옷은 빌려주니 필요 없습니다. 오후에 비가 올지도 몰라 우산만 가져갑니다.","au":"4f6a2f7f78cf"},{"part":"課題理解","q":"男の人は このあと 何を しますか。","listen":[{"s":"N","t":"会社で 女の人と 男の人が 話しています。男の人は このあと 何を しますか。"},{"s":"F","t":"山田さん、あしたの かいぎですが、二時から 四時に かわりました。"},{"s":"M","t":"そうですか。じゃ、へやの よやくも かえなければ なりませんね。"},{"s":"F","t":"へやは もう わたしが かえて おきました。すみませんが、東京の 会社の 人に れんらくして もらえますか。"},{"s":"M","t":"わかりました。メールで いいですか。"},{"s":"F","t":"いいえ、メールだと すぐ 見ないかもしれないので、電話で おねがいします。"},{"s":"M","t":"はい、すぐ します。"},{"s":"N","t":"男の人は このあと 何を しますか。"}],"choices":["へやの よやくを かえる","東京の 会社に 電話を かける","東京の 会社に メールを 送る","かいぎの しりょうを 作る"],"a":1,"ex":"방 예약은 여자가 이미 바꿨고, 메일은 안 볼 수도 있으니 「電話で おねがいします」.","au":"df8f823e95b3"},{"part":"課題理解","q":"女の人は このあと 何を しますか。","listen":[{"s":"N","t":"店で 女の人と 店の人が 話しています。女の人は このあと 何を しますか。"},{"s":"F","t":"すみません、きのう ここで この シャツを 買ったんですが、少し 小さかったので、大きいのに かえて もらえますか。"},{"s":"M","t":"はい。レシートは お持ちですか。"},{"s":"F","t":"あ、今日は 持って いません。"},{"s":"M","t":"すみません、レシートが ないと かえられないんです。"},{"s":"F","t":"そうですか。家に ありますから、とって きます。"},{"s":"M","t":"はい、お待ちして います。"},{"s":"N","t":"女の人は このあと 何を しますか。"}],"choices":["大きい シャツを 買う","シャツを 店に かえして お金を もらう","家へ レシートを とりに 帰る","ほかの 店へ 行く"],"a":2,"ex":"영수증이 없으면 교환할 수 없어서 「家に ありますから、とって きます」라고 했습니다. 지금 바로 교환하거나 새로 사지는 않습니다.","au":"c79f05061b6f"},{"part":"課題理解","q":"女の人は 何を しますか。","listen":[{"s":"N","t":"まつりの 会場で 男の人と 女の人が 話しています。女の人は 何を しますか。"},{"s":"M","t":"今日は てつだって くれて ありがとう。じゃ、ごみを あつめる 仕事を おねがいできるかな。"},{"s":"F","t":"はい。あ、でも わたし、さっき 足を いためて しまって、あまり 歩けないんです。"},{"s":"M","t":"そう。じゃ、すわって できる 仕事が いいね。うけつけで 地図を くばる 仕事は どう。"},{"s":"F","t":"はい、それなら できます。"},{"s":"M","t":"じゃ、ごみの 仕事は 山田さんに たのむよ。"},{"s":"N","t":"女の人は 何を しますか。"}],"choices":["うけつけで 地図を くばる","ごみを あつめる","山田さんを よびに 行く","会場を 歩いて あんないする"],"a":0,"ex":"다리를 다쳐 많이 못 걸어서 앉아서 할 수 있는 접수처 지도 배부를 맡습니다. 쓰레기는 山田 씨에게 부탁합니다.","au":"a620f55d6682"},{"part":"ポイント理解","q":"女の人は どうして おくれましたか。","listen":[{"s":"N","t":"会社で 男の人と 女の人が 話しています。女の人は どうして おくれましたか。"},{"s":"M","t":"おはよう。今日は おそかったね。電車が おくれたの？"},{"s":"F","t":"いえ、電車は だいじょうぶでした。じつは、駅で さいふを おとして しまって、こうばんに 行って いたんです。"},{"s":"M","t":"え、それは たいへんだったね。見つかった？"},{"s":"F","t":"はい、駅の 人が ひろって くれて いました。"},{"s":"N","t":"女の人は どうして おくれましたか。"}],"choices":["さいふを おとして、こうばんに 行ったから","電車が おくれたから","さいふを さがしに 家に 帰ったから","あさ おきるのが おそかったから"],"a":0,"ex":"전철은 괜찮았다고 부정한 뒤 「じつは、～さいふを おとして しまって、こうばんに 行って いたんです」.","au":"54810a2fdebd"},{"part":"ポイント理解","q":"二人は あした どこで 会いますか。","listen":[{"s":"N","t":"男の人と 女の人が 電話で 話しています。二人は あした どこで 会いますか。"},{"s":"M","t":"あしたの コンサート、会場の 入口で 会おうか。"},{"s":"F","t":"入口は 人が 多くて わからないかもしれないよ。駅の 北口の 本屋の 前は どう？"},{"s":"M","t":"あの 本屋は あしたは 休みだよ。じゃ、本屋の となりの きっさてんの 中は？"},{"s":"F","t":"いいね。そこなら すわって 待てるし。"},{"s":"N","t":"二人は あした どこで 会いますか。"}],"choices":["会場の 入口","本屋の 前","駅の 中の きっさてん","本屋の となりの きっさてん"],"a":3,"ex":"입구는 사람이 많고, 서점은 내일 쉬는 날이라 「本屋の となりの きっさてんの 中」로 정했습니다.","au":"d48d23d1ac3f"},{"part":"ポイント理解","q":"説明会は 何時に 始まりますか。","listen":[{"s":"N","t":"大学で 女の学生と 男の学生が 話しています。説明会は 何時に 始まりますか。"},{"s":"F","t":"あしたの りゅうがくの 説明会、何時からだっけ。"},{"s":"M","t":"お知らせには 一時からって 書いて あったけど、先生が 一時間 おそく なるって 言って いたよ。"},{"s":"F","t":"じゃ、二時からだね。"},{"s":"M","t":"うん。でも、うけつけは 三十分 前から だから、早めに 行こう。"},{"s":"N","t":"説明会は 何時に 始まりますか。"}],"choices":["1時","1時半","2時","2時半"],"a":2,"ex":"공지에는 1시였지만 선생님이 한 시간 늦어진다고 해서 2시. 접수는 30분 전(1시 반)부터라 함정입니다.","au":"b495a60c74e1"},{"part":"ポイント理解","q":"男の人は どうして くつを 買いませんでしたか。","listen":[{"s":"N","t":"女の人と 男の人が 話しています。男の人は どうして くつを 買いませんでしたか。"},{"s":"F","t":"あれ、新しい くつ、買わなかったの？"},{"s":"M","t":"うん。色も かたちも よかったんだけど。"},{"s":"F","t":"高かったの？"},{"s":"M","t":"ううん、わりびきで 安く なって いたよ。でも、ぼくの サイズが なかったんだ。"},{"s":"F","t":"そうか。ざんねんだったね。"},{"s":"N","t":"男の人は どうして くつを 買いませんでしたか。"}],"choices":["色が よくなかったから","自分の サイズが なかったから","ねだんが 高かったから","わりびきが なかったから"],"a":1,"ex":"색도 모양도 좋았고 할인으로 싸졌지만 「ぼくの サイズが なかったんだ」.","au":"984c8ccbc7e3"},{"part":"ポイント理解","q":"東京行きの 電車は 何ばんせんから 出ますか。","listen":[{"s":"N","t":"駅で アナウンスを 聞いて います。東京行きの 電車は 何ばんせんから 出ますか。"},{"s":"F","t":"お知らせします。三ばんせんから 出る よていの 東京行きの 電車は、今日は 五ばんせんから 出ます。三ばんせんでは ありません。ご注意ください。"},{"s":"N","t":"東京行きの 電車は 何ばんせんから 出ますか。"}],"choices":["2ばんせん","3ばんせん","4ばんせん","5ばんせん"],"a":3,"ex":"「三ばんせんから 出る よていの」 전철이 오늘은 「五ばんせんから 出ます」로 변경되었습니다.","au":"423d9457d4b3"},{"part":"ポイント理解","q":"女の人は どうして 料理教室に 通って いますか。","listen":[{"s":"N","t":"男の人と 女の人が 話しています。女の人は どうして 料理教室に 通って いますか。"},{"s":"M","t":"料理教室に 通って いるんだって？ 料理が 好きなの？"},{"s":"F","t":"ううん、料理は あまり 好きじゃないの。来月から 一人で 住むから、自分で 作れる ように なりたくて。"},{"s":"M","t":"そうか。教室で 友だちも できた？"},{"s":"F","t":"うん、それも うれしい ことだけどね。"},{"s":"N","t":"女の人は どうして 料理教室に 通って いますか。"}],"choices":["一人で 住むので、料理が できる ように なりたいから","料理が 好きだから","友だちを 作りたいから","先生が 有名だから"],"a":0,"ex":"요리는 별로 안 좋아하고, 다음 달부터 혼자 살아서 「自分で 作れる ように なりたくて」. 친구가 생긴 것은 덤입니다.","au":"db30aa86aedf"},{"part":"ポイント理解","q":"図書館は 来週 何曜日が 休みですか。","listen":[{"s":"N","t":"図書館で 女の人と 図書館の人が 話しています。図書館は 来週 何曜日が 休みですか。"},{"s":"F","t":"すみません、ここは 毎週 月曜日が 休みですよね。"},{"s":"M","t":"はい。でも、来週の 月曜日は しゅくじつなので 開いて います。その かわりに、火曜日が 休みに なります。"},{"s":"F","t":"そうですか。じゃ、水曜日に 来ます。"},{"s":"N","t":"図書館は 来週 何曜日が 休みですか。"}],"choices":["月曜日","火曜日","水曜日","木曜日"],"a":1,"ex":"보통은 월요일 휴관이지만 다음 주 월요일은 공휴일이라 열고 「その かわりに、火曜日が 休みに なります」.","au":"9107541210a3"},{"part":"ポイント理解","q":"送別会には ぜんぶで 何人 来ますか。","listen":[{"s":"N","t":"会社で 男の人と 女の人が 話しています。送別会には ぜんぶで 何人 来ますか。"},{"s":"M","t":"金曜日の 送別会、何人 来るか わかった？"},{"s":"F","t":"さいしょは 十五人でしたが、二人 来られなく なりました。"},{"s":"M","t":"そう。じゃ、十三人だね。"},{"s":"F","t":"あ、でも ぶちょうが おくさんと いっしょに 来るそうです。"},{"s":"M","t":"じゃ、一人 ふえて 十四人か。店に れんらくして おくよ。"},{"s":"N","t":"送別会には ぜんぶで 何人 来ますか。"}],"choices":["13人","14人","15人","16人"],"a":1,"ex":"15명에서 2명이 빠져 13명, 부장님 부인이 함께 와서 「一人 ふえて 十四人」.","au":"1de2b9f70f93"},{"part":"読み","q":"電車が 出ますから、<u>急いで<\/u> ください。","choices":["およいで","さわいで","いそいで","きゅういで"],"a":2,"ex":"急ぐ(いそぐ, 서두르다)의 て형 いそいで. 急은 음독 きゅう(急行 등)도 있지만 동사는 いそぐ."},{"part":"表記","q":"駅の <u>でぐち<\/u>で 待って います。","choices":["山口","出目","土口","出口"],"a":3,"ex":"でぐち(출구)는 出口. 山口는 やまぐち(지명·성)입니다."},{"part":"文脈","q":"駅まで 走ったので、電車に （　　）。","choices":["足りました","急ぎました","間に合いました","こみました"],"a":2,"ex":"「電車に 間に合う」(전철 시간에 늦지 않다). 急ぐ는 「電車に」와 함께 쓰지 않습니다."},{"part":"言い換え","q":"この 店は 日曜日は いつも <u>こんで います<\/u>。","choices":["人が 多いです","人が 少ないです","しずかです","休みです"],"a":0,"ex":"こむ(붐비다)＝사람이 많다. 반대는 すいて いる."}],"shadow":{"jp":"先に うけつけで 名前を 書いてから、会場に 入って ください。","r":"さきに うけつけで なまえを かいてから、かいじょうに はいって ください。","ko":"먼저 접수처에서 이름을 쓰고 나서 행사장에 들어가 주세요.","au":"9d7ead52ec41"}},{"day":4,"title":"발화 표현·즉시 응답 듣기","vocab":[{"w":"しょうたい","r":"しょうたい","m":"초대 (招待)","au":"f744b8d480f7","rep":1},{"w":"さそう","r":"さそう","m":"(같이 하자고) 권하다, 초대하다 (誘う)","au":"ba2655ef448a","rep":1},{"w":"ことわる","r":"ことわる","m":"거절하다 (断る)","au":"4483df1fd621"},{"w":"おいわい","r":"おいわい","m":"축하, 축하 선물 (お祝い)","au":"9ee2ae70d9fd","rep":1},{"w":"よろこぶ","r":"よろこぶ","m":"기뻐하다 (喜ぶ)","au":"68e38ec88e01","rep":1},{"w":"えんりょ","r":"えんりょ","m":"사양, 삼감 (遠慮)","au":"226e6deb48f4","rep":1},{"w":"てつだう","r":"てつだう","m":"돕다, 거들다 (手伝う)","au":"2cf20612d8b1"},{"w":"送別会","r":"そうべつかい","m":"송별회","au":"1ffe6a9e90f9"},{"w":"都合","r":"つごう","m":"형편, 사정","au":"f8ce96e1297e","rep":1},{"w":"へんじ","r":"へんじ","m":"대답, 답장 (返事)","au":"7dc503af5bf5","rep":1},{"w":"しゅっせき","r":"しゅっせき","m":"출석, 참석 (出席)","au":"250e815e7a0c"},{"w":"けっせき","r":"けっせき","m":"결석, 불참 (欠席)","au":"55cf247cb76e"},{"w":"かんぱい","r":"かんぱい","m":"건배 (乾杯)","au":"87bda94d3de6"},{"w":"お土産","r":"おみやげ","m":"선물, 여행 기념품","au":"dfcf4e1a20b2","rep":1},{"w":"ざんねん","r":"ざんねん","m":"유감, 아쉬움 (残念)","au":"a4d603094ae0","rep":1}],"lesson":{"summary":"발화 표현은 그림 속 사람이 할 말, 즉시 응답은 짧은 말에 대한 알맞은 대답을 고르는 문제입니다. 인사·부탁·권유·제안·사양 표현을 상황과 함께 외워 두면 빨리 풀 수 있습니다.","points":["発話表現: 상황 설명에서 '누가 → 누구에게 → 무엇을 하고 싶은지'를 먼저 확인하세요. 부탁하는지, 허가를 구하는지, 권하는지, 도와주겠다고 하는지 구분합니다.","자주 나오는 형태: 부탁 「～て いただけませんか」「～て もらえますか」 / 허가 「～ても いいですか」 / 권유 「～ませんか」 / 제안 「～ましょうか」「お～しましょうか」(제가 ~해 드릴까요).","即時応答: 문장 끝을 잘 들으세요. 「～ましょうか」(제가 할까요?)에는 「おねがいします」, 「～ませんか」(같이 할래요?)에는 「いいですね」, 사과에는 「いいえ、気に しないで ください」.","함정: 들은 말의 단어를 그대로 반복하는 대답, 시제가 틀린 대답(しゅっせきしますか → しゅっせきしました), 입장이 반대인 인사(行って きます ↔ 行って らっしゃい).","음성은 한 번만 나오고 바로 다음 문제로 넘어갑니다. 망설이지 말고 바로 고르세요."],"table":{"head":["듣는 말","알맞은 대답"],"rows":[["てつだいましょうか。","ありがとう ございます。おねがいします。"],["いっしょに 行きませんか。","いいですね。行きましょう。"],["お先に しつれいします。","おつかれさまでした。"],["おまたせしました。","いいえ、わたしも 今 来た ところです。"],["えんりょしないで 食べて ください。","じゃ、いただきます。"],["行って きます。","行って らっしゃい。"]]},"examples":[{"jp":"すみません、写真を とって いただけませんか。","r":"すみません、しゃしんを とって いただけませんか。","ko":"죄송하지만 사진을 찍어 주실 수 없을까요?","au":"e0b7e2430b04"},{"jp":"にもつ、お持ちしましょうか。","r":"にもつ、おもちしましょうか。","ko":"짐, 들어 드릴까요?","au":"91c444dc39e0"},{"jp":"この 本、借りても いいですか。","r":"この ほん、かりても いいですか。","ko":"이 책 빌려도 되나요?","au":"e9395186114f"},{"jp":"今度の 土曜日、いっしょに 花火を 見に 行きませんか。","r":"こんどの どようび、いっしょに はなびを みに いきませんか。","ko":"이번 토요일에 같이 불꽃놀이 보러 가지 않을래요?","au":"cebdee5a389c"}]},"drills":[{"part":"発話表現","q":"[그림] 친구에게 토요일 불꽃놀이를 같이 보러 가자고 권하고 싶습니다.","listen":[{"s":"N","t":"友だちを 花火に さそいたいです。何と 言いますか。"}],"spoken":["土曜日、花火を 見に 行って きましたか。","土曜日、いっしょに 花火を 見に 行きませんか。","土曜日、花火を 見に 行っても いいですか。"],"choices":["1","2","3"],"a":1,"ex":"권유는 「～ませんか」. 「行って きましたか」는 다녀왔는지 묻는 말, 「行っても いいですか」는 허가를 구하는 말입니다.","au":"b34e89334a31"},{"part":"発話表現","q":"[그림] 선생님이 무거운 짐을 들고 있습니다. 들어 드리겠다고 하고 싶습니다.","listen":[{"s":"N","t":"先生の にもつが 重そうです。何と 言いますか。"}],"spoken":["先生、お持ちしましょうか。","先生、持って いただけませんか。","先生、持って くださって ありがとう ございます。"],"choices":["1","2","3"],"a":0,"ex":"내가 해 드리겠다는 제안은 겸양 「お～しましょうか」. 「持って いただけませんか」는 선생님께 들어 달라고 부탁하는 말입니다.","au":"208a089d1b32"},{"part":"発話表現","q":"[그림] 파티에 초대받았지만 그날은 갈 수 없어서 거절합니다.","listen":[{"s":"N","t":"パーティーに さそわれましたが、その 日は 行けません。何と 言いますか。"}],"spoken":["はい、ぜひ 行かせて ください。","どうぞ、えんりょしないで 来て ください。","すみません、その 日は ちょっと 都合が わるいんです。"],"choices":["1","2","3"],"a":2,"ex":"거절은 「その 日は ちょっと 都合が わるい」처럼 돌려 말합니다. 「ぜひ 行かせて ください」는 수락, 「えんりょしないで 来て」는 초대하는 쪽의 말.","au":"c31effba20ee"},{"part":"発話表現","q":"[그림] 송별회에서 모두 잔을 들었습니다. 지금부터 마시려고 합니다.","listen":[{"s":"N","t":"送別会で みんなが 飲み物を 持って います。これから 飲みます。何と 言いますか。"}],"spoken":["では、かんぱい！","では、ごちそうさまでした。","では、おじゃまします。"],"choices":["1","2","3"],"a":0,"ex":"마시기 시작할 때는 「かんぱい」(건배). 「ごちそうさまでした」는 다 먹은 뒤, 「おじゃまします」는 남의 집에 들어갈 때.","au":"5375391f46ca"},{"part":"発話表現","q":"[그림] 여행에서 사 온 기념품을 회사 사람들에게 건네려고 합니다.","listen":[{"s":"N","t":"旅行の お土産を 会社の 人に わたします。何と 言いますか。"}],"spoken":["これ、旅行の お土産です。いただきます。","これ、旅行の お土産ですか。ありがとう ございます。","これ、旅行の お土産です。みなさんで どうぞ。"],"choices":["1","2","3"],"a":2,"ex":"건네는 쪽은 「どうぞ」. 「いただきます」「ありがとう ございます」는 받는 쪽의 말입니다.","au":"7437442c35a5"},{"part":"発話表現","q":"[그림] 친구가 결혼하게 되었다고 말했습니다. 축하하고 싶습니다.","listen":[{"s":"N","t":"友だちが けっこんする ことに なりました。何と 言いますか。"}],"spoken":["けっこん、ざんねんだったね。","けっこん、おめでとう！","けっこん、おだいじに。"],"choices":["1","2","3"],"a":1,"ex":"축하는 「おめでとう」. 「おだいじに」는 아픈 사람에게 하는 말입니다.","au":"9e6a14a54f32"},{"part":"発話表現","q":"[그림] 선생님 방의 문을 노크했습니다. 들어가고 싶습니다.","listen":[{"s":"N","t":"先生の へやに 入りたいです。何と 言いますか。"}],"spoken":["どうぞ、入って ください。","おじゃましました。","しつれいします。入っても よろしいですか。"],"choices":["1","2","3"],"a":2,"ex":"허가를 구할 때는 「～ても よろしいですか」. 「どうぞ、入って ください」는 방 안의 선생님이 하는 말, 「おじゃましました」는 나올 때 인사.","au":"c7b17824e071"},{"part":"発話表現","q":"[그림] 친구가 이사 준비로 바빠 보입니다. 도와주겠다고 하고 싶습니다.","listen":[{"s":"N","t":"友だちが ひっこしの じゅんびで いそがしそうです。何と 言いますか。"}],"spoken":["何か てつだおうか。","てつだって くれない？","てつだって くれて ありがとう。"],"choices":["1","2","3"],"a":0,"ex":"도와주겠다는 제안은 의지형 「てつだおうか」. 「てつだって くれない」는 도와 달라는 부탁입니다.","au":"ef6242f89362"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"F","t":"あしたの 送別会、しゅっせきしますか。"}],"spoken":["はい、しゅっせきしました。","はい、行く つもりです。","いいえ、送別会でした。"],"choices":["1","2","3"],"a":1,"ex":"내일 일을 물었으므로 「行く つもりです」. 「しゅっせきしました」는 과거라 시제가 맞지 않습니다.","au":"a45632aa8dd7"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"M","t":"よかったら この ケーキ、どうぞ。えんりょしないで くださいね。"}],"spoken":["じゃ、いただきます。","いいえ、どういたしまして。","はい、ごちそうさまでした。"],"choices":["1","2","3"],"a":0,"ex":"권하는 음식을 받을 때는 「いただきます」. 「ごちそうさまでした」는 다 먹은 뒤의 인사.","au":"51b52c28d318"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"F","t":"この 前は てつだって くれて、ありがとう。"}],"spoken":["いいえ、てつだって ください。","いいえ、どういたしまして。","はい、ありがとう ございました。"],"choices":["1","2","3"],"a":1,"ex":"감사 인사에는 「どういたしまして」. 같은 말(ありがとう)을 되돌리는 것은 함정.","au":"72978135df11"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"M","t":"来週の パーティー、都合は どうですか。"}],"spoken":["はい、パーティーでした。","ええ、都合が いいでしょう。","すみません、その 日は ちょっと 用事が あって。"],"choices":["1","2","3"],"a":2,"ex":"사정을 묻는 말에 볼일이 있다고 완곡하게 답합니다. 자기 사정에 「でしょう」(추측)는 부자연스럽습니다.","au":"5fbd1cf6a3c1"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"F","t":"へんじが おそく なって、すみません。"}],"spoken":["いいえ、気に しないで ください。","いいえ、おそく なりましょう。","はい、すみませんでした。"],"choices":["1","2","3"],"a":0,"ex":"사과에는 「気に しないで ください」(신경 쓰지 마세요). 상대 사과에 같이 사과하는 것은 함정.","au":"7ca441da61de"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"M","t":"コーヒーと こうちゃと、どちらが いいですか。"}],"spoken":["はい、どちらでも ありません。","じゃ、コーヒーを おねがいします。","いいえ、コーヒーです。"],"choices":["1","2","3"],"a":1,"ex":"「どちらが いいですか」에는 하나를 골라 「～を おねがいします」. はい/いいえ로 답하는 질문이 아닙니다.","au":"c61aff9d65d9"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"F","t":"じゃ、行って きます。"}],"spoken":["行って きます。","おかえりなさい。","行って らっしゃい。気を つけてね。"],"choices":["1","2","3"],"a":2,"ex":"나가는 사람의 「行って きます」에는 「行って らっしゃい」. 「おかえりなさい」는 돌아왔을 때.","au":"d914c7b4db5a"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"M","t":"日曜日、みんなで バーベキューを するんだけど、来ない？"}],"spoken":["いいね。何か 持って いこうか。","うん、来ないよ。","へえ、だれが 来なかったの。"],"choices":["1","2","3"],"a":0,"ex":"「来ない」는 '안 올래?'라는 권유. 수락하면서 뭘 가져갈지 묻는 것이 자연스럽습니다.","au":"8ebe9d09ce17"},{"part":"文法形式","q":"先生、すみませんが、この 作文を 見て （　　）。","choices":["もらいませんか","あげませんか","さしあげませんか","いただけませんか"],"a":3,"ex":"윗사람에게 정중하게 부탁할 때 「～て いただけませんか」. 「あげませんか」「さしあげませんか」는 내가 해 주는 쪽입니다."},{"part":"文法形式","q":"ぶちょう、その にもつ、わたしが （　　）。","choices":["お持ちに なりましょうか","持って いただきましょうか","お持ちください","お持ちしましょうか"],"a":3,"ex":"내가 해 드리는 겸양 제안은 「お～しましょうか」. 「お～に なる」는 상대의 동작을 높이는 존경어입니다."},{"part":"組み立て","q":"A「あしたの 送別会、来られますか。」<br>B「すみません。あしたは ＿＿ ＿＿ <b>★<\/b> ＿＿ ので、行けないんです。」","choices":["母が","国から","ことに なって いる","来る"],"a":3,"ex":"완성: 「あしたは 母が 国から 来る ことに なって いる ので、行けないんです。」 ★은 「来る」. (母が와 国から는 순서가 바뀌어도 ★은 같습니다.)"},{"part":"組み立て","q":"A「送別会の あんない、読みましたか。」<br>B「はい。金曜日までに ＿＿ ＿＿ <b>★<\/b> ＿＿ ならないんですよね。」","choices":["しゅっせきか","けっせきか","しなければ","へんじを"],"a":3,"ex":"완성: 「金曜日までに しゅっせきか けっせきか へんじを しなければ ならないんですよね。」 ★은 「へんじを」."}],"shadow":{"jp":"すみません、その 日は ちょっと 都合が わるいんです。","r":"すみません、その ひは ちょっと つごうが わるいんです。","ko":"죄송해요, 그날은 좀 사정이 안 돼서요.","au":"16c1aa8894eb"}},{"day":5,"title":"10주 복습: 독해·청해 실전 혼합","vocab":[],"lesson":{"summary":"이번 주에 익힌 독해·청해 풀이 순서를 실전처럼 섞어서 적용합니다. 독해 10문제는 20분 안에, 청해는 음성을 한 번만 듣고 풀어 보세요.","points":["短文: 질문 먼저 → 부탁·마감 문장(～てください・～までに) 찾기. 中文: 질문 순서 = 글의 순서, 생각·기분 문장(～と思いました) 찾기.","情報検索: 조건에 표시 → 표에서 해당 줄만 → ※·ただし 확인 → 계산은 마지막에.","文章の文法: 빈칸 앞뒤 문장의 관계(접속사), 글쓴이 입장(문말), 시제를 확인.","課題理解: '이미 한 일·안 해도 되는 일' 지우기. ポイント理解: 정정 표현(いえ・でも・じつは) 뒤가 정답.","発話表現・即時応答: 말하는 사람의 입장(부탁·허가·권유·제안)과 문말 표현을 듣고 바로 고르기."],"table":{"head":["유형","목표 시간","핵심"],"rows":[["短文","1문제 2~3분","질문 먼저, 부탁·마감 문장"],["中文","지문 1개 5~6분","질문 순서대로, 생각 문장"],["情報検索","1문제 3분","조건 표시, ※ 확인"],["文章の文法","1문제 1분","접속사·문말·시제"],["課題理解","음성 1회","이미 한 일 지우기"],["ポイント理解","음성 1회","정정 뒤가 정답"],["発話表現・即時応答","바로 선택","입장과 문말"]]},"examples":[{"jp":"おべんとうは いりません。飲み物だけ 持って きて ください。","r":"おべんとうは いりません。のみものだけ もって きて ください。","ko":"도시락은 필요 없습니다. 음료만 가져와 주세요.","au":"36f26a624cbd"},{"jp":"ただし、小学生は 大人と いっしょに 来て ください。","r":"ただし、しょうがくせいは おとなと いっしょに きて ください。","ko":"단, 초등학생은 어른과 함께 와 주세요.","au":"c2b108613b51"},{"jp":"いえ、駅の 前じゃなくて、本屋の 中で 会いましょう。","r":"いえ、えきの まえじゃなくて、ほんやの なかで あいましょう。","ko":"아뇨, 역 앞이 아니라 서점 안에서 만나요.","au":"26347e49ccab"}]},"drills":[{"part":"短文","q":"（山田さんが 病院から メールを もらいました。）<br>山田さま<br>11月18日（火）午後3時の よやくですが、先生の 都合で、その 日は みる ことが できなく なりました。もうしわけ ありません。11月19日（水）か 20日（木）の 同じ 時間は いかがでしょうか。都合の いい 日を 17日までに お電話で 教えて ください。<br>さくら病院<br><br>山田さんは 何を しなければ なりませんか。","choices":["18日の 3時に 病院へ 行く。","17日までに メールで 行ける 日を 送る。","19日と 20日に 病院へ 行く。","17日までに 病院に 電話して、行ける 日を 言う。"],"a":3,"ex":"「都合の いい 日を 17日までに お電話で 教えて ください」. 메일이 아니라 전화이고, 18일 예약은 취소되었습니다."},{"part":"短文","q":"（学校の けいじばんに この お知らせが あります。）<br>わすれものに ついて<br>教室に わすれものが たくさん あります。1かいの じむしょで あずかって います。12月20日までに とりに 来ない ものは すてますので、気を つけて ください。とりに 来る ときは、がくせいしょうを 見せて ください。<br>じむしょ<br><br>わすれものを とりに 行く 人は、どう しますか。","choices":["12月20日の 後で 教室へ とりに 行く。","12月20日までに がくせいしょうを 持って じむしょへ 行く。","がくせいしょうを 持って 教室へ 行く。","じむしょに 電話を して、送って もらう。"],"a":1,"ex":"분실물은 1층 사무실에 있고, 20일까지 학생증을 보여 주고 찾아야 합니다. 교실에는 없습니다."},{"part":"短文","q":"（会社で 林さんの つくえの 上に この メモが あります。）<br>林さん<br>さっき 山川電気の 小林さんから 電話が ありました。あしたの やくそくの 時間を 10時から 11時に かえて ほしいそうです。林さんの 都合が わるければ、今日の 5時までに 小林さんに 電話して ください。都合が よければ、れんらくは いらないそうです。<br>3時20分　中村<br><br>林さんは あした 11時に 小林さんに 会う ことが できます。林さんは どう しますか。","choices":["今日の 5時までに 小林さんに 電話する。","あした 10時に 小林さんに 会う。","小林さんに れんらくしないで、あした 11時に 会う。","中村さんに 電話を して もらう。"],"a":2,"ex":"11시로 바꾸고 싶다는 부탁이고, 형편이 좋으면 「れんらくは いらない」. 전화는 형편이 나쁠 때만 합니다."},{"part":"中文","q":"（会社員が 書いた 作文です。）<br>先月、近くの こうえんで フリーマーケットが ありました。わたしは 使わなく なった 服や 本を 売って みる ことに しました。前の 日に、ねだんを 書いた 紙を 用意しました。服は 1まい 300円、本は 1さつ 100円に しました。<br>その 日は 朝 8時に こうえんへ 行きました。朝の うちは あまり 売れませんでしたが、昼ごろから お客さんが ふえて きました。小さい 子どもを つれた お母さんが、子どもの 服を 5まいも 買って くれました。<br>終わってから かぞえると、売れた お金は 3,500円でした。あまり 多くないと 思うかもしれませんが、わたしは とても うれしかったです。わたしが もう 使わない 物を、ほかの 人が よろこんで 使って くれるからです。次の フリーマーケットにも 出したいと 思います。<br><br>この 人は どうして うれしかったのですか。","choices":["自分が 使わない 物を、ほかの 人が 使って くれるから","売れた お金が とても 多かったから","子どもの 服が ぜんぶ 売れたから","昼ごろから こうえんに 人が ふえたから"],"a":0,"ex":"「～ほかの 人が よろこんで 使って くれるからです」가 이유. 금액은 「あまり 多くない」라고 스스로 말했습니다."},{"part":"中文","q":"（会社員が 書いた 作文です。）<br>先月、近くの こうえんで フリーマーケットが ありました。わたしは 使わなく なった 服や 本を 売って みる ことに しました。前の 日に、ねだんを 書いた 紙を 用意しました。服は 1まい 300円、本は 1さつ 100円に しました。<br>その 日は 朝 8時に こうえんへ 行きました。朝の うちは あまり 売れませんでしたが、昼ごろから お客さんが ふえて きました。小さい 子どもを つれた お母さんが、子どもの 服を 5まいも 買って くれました。<br>終わってから かぞえると、売れた お金は 3,500円でした。あまり 多くないと 思うかもしれませんが、わたしは とても うれしかったです。わたしが もう 使わない 物を、ほかの 人が よろこんで 使って くれるからです。次の フリーマーケットにも 出したいと 思います。<br><br>この 人に ついて 正しい ものは どれですか。","choices":["服は 1まい 100円で 売った。","お母さんが 本を 5さつ 買って くれた。","朝の うちは 品物が あまり 売れなかった。","もう フリーマーケットには 出ない つもりだ。"],"a":2,"ex":"「朝の うちは あまり 売れませんでしたが」. 옷은 300엔, 엄마가 산 것은 아이 옷 5벌, 다음에도 나가고 싶다고 했습니다."},{"part":"情報検索","q":"（市民センターの あんないです。）<br>【みなみ市民センター 12月の イベント】<br>① 英語で 話そう　12月6日（土）10:00～12:00　500円　高校生 以上<br>② クリスマスカード作り　12月13日（土）14:00～16:00　むりょう　小学生 以上（小学生は 大人と いっしょに）<br>③ そばを 作ろう　12月14日（日）10:00～13:00　1,500円　20さい 以上<br>④ 親子ダンス　12月20日（土）13:00～14:30　1くみ 800円　3さい～小学生と その 親<br>※ もうしこみは イベントの 3日前までに 電話で。②は もうしこみは いりません。<br><br>大学生の ジョンさん（21さい）は、12月の 週末の 午前中に 何か したいです。お金は 1,000円 以下が いいです。どれが いいですか。","choices":["② クリスマスカード作り","③ そばを 作ろう","④ 親子ダンス","① 英語で 話そう"],"a":3,"ex":"오전 행사는 ①과 ③. ③은 1,500엔이라 조건에 안 맞고, ①은 500엔·고등학생 이상이라 가능합니다."},{"part":"情報検索","q":"（市民センターの あんないです。）<br>【みなみ市民センター 12月の イベント】<br>① 英語で 話そう　12月6日（土）10:00～12:00　500円　高校生 以上<br>② クリスマスカード作り　12月13日（土）14:00～16:00　むりょう　小学生 以上（小学生は 大人と いっしょに）<br>③ そばを 作ろう　12月14日（日）10:00～13:00　1,500円　20さい 以上<br>④ 親子ダンス　12月20日（土）13:00～14:30　1くみ 800円　3さい～小学生と その 親<br>※ もうしこみは イベントの 3日前までに 電話で。②は もうしこみは いりません。<br><br>小学2年生の むすめと 母親が、12月13日の イベントに 行きたいです。どう すれば いいですか。","choices":["もうしこみは しないで、その 日に 二人で センターへ 行く。","12月10日までに 電話で もうしこむ。","800円 はらって、センターへ 行く。","むすめだけで センターへ 行かせる。"],"a":0,"ex":"13일은 ② 무료 행사이고 「②は もうしこみは いりません」. 초등학생은 어른과 함께 와야 합니다."},{"part":"文章の文法","q":"わたしの 家の 近くに 小さい 図書館が あります。この 図書館では、毎月 いろいろな イベントが あります。先月は、日本の むかし話を 聞く 会に <b>[ 1 ]<\/b>。子どもが 多いと 思って いましたが、大人も たくさん 来て いました。話して くれた おばあさんは とても 上手で、日本語が よく わからない わたしにも、話が よく わかりました。[ 2 ]、会の 後で、おばあさんが 話の 中の ことばの いみを 教えて くれました。図書館の 人に よると、来月は 紙で にんぎょうを 作る 会が ある [ 3 ]。今から 楽しみです。<br><br><b>[ 1 ]<\/b>に 入る ものは どれですか。","choices":["さんかする つもりです","さんかして みました","さんかさせて ください","さんかした ことが ありません"],"a":1,"ex":"지난달(先月) 실제로 참가한 경험을 말하므로 「さんかして みました」. 「つもりです」는 미래라 시제가 맞지 않습니다."},{"part":"文章の文法","q":"わたしの 家の 近くに 小さい 図書館が あります。この 図書館では、毎月 いろいろな イベントが あります。先月は、日本の むかし話を 聞く 会に [ 1 ]。子どもが 多いと 思って いましたが、大人も たくさん 来て いました。話して くれた おばあさんは とても 上手で、日本語が よく わからない わたしにも、話が よく わかりました。<b>[ 2 ]<\/b>、会の 後で、おばあさんが 話の 中の ことばの いみを 教えて くれました。図書館の 人に よると、来月は 紙で にんぎょうを 作る 会が ある [ 3 ]。今から 楽しみです。<br><br><b>[ 2 ]<\/b>に 入る ものは どれですか。","choices":["それに","それとも","たとえば","ところが"],"a":0,"ex":"이야기가 잘 이해됐다 + 끝나고 단어 뜻도 가르쳐 주었다: 좋은 일을 덧붙이는 「それに」(게다가)."},{"part":"文章の文法","q":"わたしの 家の 近くに 小さい 図書館が あります。この 図書館では、毎月 いろいろな イベントが あります。先月は、日本の むかし話を 聞く 会に [ 1 ]。子どもが 多いと 思って いましたが、大人も たくさん 来て いました。話して くれた おばあさんは とても 上手で、日本語が よく わからない わたしにも、話が よく わかりました。[ 2 ]、会の 後で、おばあさんが 話の 中の ことばの いみを 教えて くれました。図書館の 人に よると、来月は 紙で にんぎょうを 作る 会が ある <b>[ 3 ]<\/b>。今から 楽しみです。<br><br><b>[ 3 ]<\/b>に 入る ものは どれですか。","choices":["つもりです","ことに します","ところです","そうです"],"a":3,"ex":"「図書館の 人に よると」(도서관 직원에 따르면)는 전문 「～そうです」와 짝입니다."},{"part":"課題理解","q":"男の人は 次に 来る とき、何を 持って きますか。","listen":[{"s":"N","t":"図書館で 男の人と 図書館の人が 話しています。男の人は 次に 来る とき、何を 持って きますか。"},{"s":"M","t":"すみません、本を 借りる カードを 作りたいんですが。"},{"s":"F","t":"はい。住所が わかる ものは ありますか。"},{"s":"M","t":"がくせいしょうなら あります。"},{"s":"F","t":"すみません、がくせいしょうには 住所が 書いて ありませんね。写真は いりませんが、住所が 書いて ある カード、たとえば ほけんの カードは ありますか。"},{"s":"M","t":"今日は 持って いません。住所が 書いて ある 手紙なら ありますが。"},{"s":"F","t":"すみません、手紙では 作れないんです。"},{"s":"M","t":"わかりました。じゃ、次は ほけんの カードを 持って きます。"},{"s":"N","t":"男の人は 次に 来る とき、何を 持って きますか。"}],"choices":["がくせいしょう","写真","ほけんの カード","住所が 書いて ある 手紙"],"a":2,"ex":"학생증에는 주소가 없고 편지는 안 되며 사진은 필요 없다고 했습니다. 「ほけんの カードを 持って きます」.","au":"904d1e40e439"},{"part":"課題理解","q":"女の人は このあと まず 何を しますか。","listen":[{"s":"N","t":"会社で 男の人と 女の人が 話しています。女の人は このあと まず 何を しますか。"},{"s":"M","t":"来週の イベントの ポスター、もう できた？"},{"s":"F","t":"はい、さっき できました。今から コピーして、駅の 近くの 店に はりに 行きます。"},{"s":"M","t":"あ、コピーする 前に、ぼくに 一度 見せて くれる？日にちが まちがって いないか 見たいから。"},{"s":"F","t":"はい。じゃ、すぐ 持って きます。"},{"s":"N","t":"女の人は このあと まず 何を しますか。"}],"choices":["ポスターを コピーする","ポスターを 男の人に 見せる","駅の 近くの 店に ポスターを はる","ポスターを 作りなおす"],"a":1,"ex":"복사해서 붙이러 가려 했지만 「コピーする 前に、ぼくに 一度 見せて」라는 말에 먼저 보여 줍니다.","au":"c009c184016d"},{"part":"課題理解","q":"二人は 何を 買いますか。","listen":[{"s":"N","t":"女の人と 男の人が 話しています。二人は 何を 買いますか。"},{"s":"F","t":"山田さんの 送別会の プレゼント、何が いいかな。花は どう？"},{"s":"M","t":"花は 会社の みんなから わたすって 聞いたよ。"},{"s":"F","t":"そうか。じゃ、本は？ 山田さん、本が 好きだし。"},{"s":"M","t":"でも、どんな 本が 好きか わからないよね。山田さん、毎朝 コーヒーを 飲んで いるから、コーヒーカップは どう？"},{"s":"F","t":"いいね。それに しよう。"},{"s":"N","t":"二人は 何を 買いますか。"}],"choices":["花","コーヒーカップ","本","コーヒー"],"a":1,"ex":"꽃은 회사 사람들이 주고, 책은 취향을 몰라서 제외. 매일 커피를 마시니까 「コーヒーカップ」로 정했습니다.","au":"98faea9ae332"},{"part":"ポイント理解","q":"男の人は どうして パーティーに 行けませんか。","listen":[{"s":"N","t":"女の人と 男の人が 話しています。男の人は どうして パーティーに 行けませんか。"},{"s":"F","t":"土曜日の パーティー、来られる？"},{"s":"M","t":"ごめん、行けないんだ。"},{"s":"F","t":"アルバイト？"},{"s":"M","t":"ううん、アルバイトは 休みを もらったんだけど、国から りょうしんが 来るんだ。くうこうまで むかえに 行かなきゃ ならなくて。"},{"s":"F","t":"そうなんだ。じゃ、また 今度ね。"},{"s":"N","t":"男の人は どうして パーティーに 行けませんか。"}],"choices":["りょうしんを むかえに 行くから","アルバイトが あるから","国へ 帰るから","体の ちょうしが わるいから"],"a":0,"ex":"아르바이트는 쉬는 날을 받았고, 고향에서 부모님이 와서 「くうこうまで むかえに 行かなきゃ」.","au":"12e007892858"},{"part":"ポイント理解","q":"セールを して いるのは どこですか。","listen":[{"s":"N","t":"デパートで アナウンスを 聞いて います。セールを して いるのは どこですか。"},{"s":"F","t":"今日も みどりデパートに 来て いただいて、ありがとう ございます。ただいま、五かいの 服の 売り場で セールを して います。なお、四かいの くつ売り場の セールは きのうで 終わりました。ぜひ 五かいへ どうぞ。"},{"s":"N","t":"セールを して いるのは どこですか。"}],"choices":["4かいの 服売り場","4かいの くつ売り場","5かいの 服売り場","5かいの くつ売り場"],"a":2,"ex":"「五かいの 服の 売り場で セールを して います」. 4층 구두 매장 세일은 「きのうで 終わりました」.","au":"9f231ae8cc25"},{"part":"ポイント理解","q":"二人は あした 何時に 会いますか。","listen":[{"s":"N","t":"男の人と 女の人が 電話で 話しています。二人は あした 何時に 会いますか。"},{"s":"M","t":"あしたの えいが、十時のを 見る？"},{"s":"F","t":"十時は ちょっと 早いなあ。次は 何時？"},{"s":"M","t":"十二時半だよ。その 前に ごはんを 食べようか。"},{"s":"F","t":"いいね。じゃ、えいがの 一時間 前に 会おう。"},{"s":"M","t":"うん、わかった。"},{"s":"N","t":"二人は あした 何時に 会いますか。"}],"choices":["10時","11時半","12時","12時半"],"a":1,"ex":"10시 영화는 이르다고 해서 12시 반 영화로, 그 한 시간 전(11시 반)에 만나서 밥을 먹기로 했습니다.","au":"a11fad14a08d"},{"part":"発話表現","q":"[그림] 도서관에서 옆자리에 앉고 싶습니다. 옆 사람에게 물어봅니다.","listen":[{"s":"N","t":"となりの せきに すわりたいです。何と 言いますか。"}],"spoken":["すみません、ここに すわって ください。","すみません、どうぞ すわって いて ください。","すみません、ここ、いいですか。"],"choices":["1","2","3"],"a":2,"ex":"앉아도 되는지 허가를 구하는 「ここ、いいですか」. 나머지는 상대에게 앉으라고 권하는 말입니다.","au":"6caa19061fd0"},{"part":"発話表現","q":"[그림] 친구에게 빌렸던 우산을 돌려줍니다.","listen":[{"s":"N","t":"友だちに 借りた かさを かえします。何と 言いますか。"}],"spoken":["かさ、ありがとう。たすかったよ。","かさ、かして くれない。","かさ、どうぞ 使って。"],"choices":["1","2","3"],"a":0,"ex":"돌려줄 때는 고마움을 전합니다. 「かして くれない」는 빌려 달라는 말, 「どうぞ 使って」는 빌려주는 쪽의 말.","au":"ce4a5b18b55e"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"M","t":"この しりょう、コピーしましょうか。"}],"spoken":["はい、コピーしましょう。","あ、おねがいします。","いいえ、コピーでした。"],"choices":["1","2","3"],"a":1,"ex":"「～ましょうか」(제가 ~할까요?)라는 제안에는 「おねがいします」. 「コピーしましょう」는 같이 하자는 말이 되어 어색합니다.","au":"8bbacfe43130"},{"part":"即時応答","q":"듣고 가장 알맞은 대답을 고르세요.","listen":[{"s":"F","t":"おまたせしました。"}],"spoken":["はい、待って ください。","いいえ、おまたせしました。","いいえ、わたしも 今 来た ところです。"],"choices":["1","2","3"],"a":2,"ex":"「おまたせしました」(기다리셨죠)에는 「今 来た ところです」(방금 왔어요). 같은 말 반복은 함정.","au":"a5b31edaea5b"},{"part":"読み","q":"会場の <u>入口<\/u>で チケットを 見せて ください。","choices":["いりくち","はいりぐち","にゅうこう","いりぐち"],"a":3,"ex":"入口는 いりぐち(口가 ぐち로 탁음화). 「はいりぐち」는 틀린 읽기입니다."},{"part":"文脈","q":"雨が ふったので、きのうの 花火大会は （　　）に なりました。","choices":["注意","開始","用意","中止"],"a":3,"ex":"비 때문에 행사가 취소된 것은 中止. 「～に なりました」와 자연스럽게 이어집니다."},{"part":"文法形式","q":"A「すみません、ここで 写真を （　　）。」<br>B「ここは だめですが、あちらなら だいじょうぶですよ。」","choices":["とっても いいですか","とって おきましたか","とって しまいますか","とる ことに しますか"],"a":0,"ex":"B가 '여기는 안 되지만 저기는 괜찮다'고 답하므로 허가를 구하는 「～ても いいですか」."},{"part":"組み立て","q":"A「この イベント、だれでも さんか できますか。」<br>B「いいえ、＿＿ ＿＿ <b>★<\/b> ＿＿ さんか できません。」","choices":["20さい","以上の","しか","人"],"a":3,"ex":"완성: 「20さい 以上の 人 しか さんか できません。」 ★은 세 번째 「人」."},{"part":"表記","q":"<u>りょうきん<\/u>は 入口で はらって ください。","choices":["科金","料全","料金","料今"],"a":2,"ex":"りょうきん은 料金. 科(과)·全(전)·今(금)은 모양이 비슷한 다른 한자입니다."}],"shadow":{"jp":"質問を 先に 読んでから、答えを さがしましょう。","r":"しつもんを さきに よんでから、こたえを さがしましょう。","ko":"질문을 먼저 읽고 나서 답을 찾읍시다.","au":"700ed2e0d74a"}}]};
